# --------------------------------------------------------------------------- helpers
def _G_iso_z(t: datetime) -> str:
    return t.astimezone(_GUTC).strftime("%Y-%m-%dT%H:%M:%SZ")


def _G_write(path: Path, text: str) -> None:
    path.write_text(text, encoding="utf-8", newline="\n")


def _G_csv_text(header: list[str], rows: list[list[object]], delim: str = ",") -> str:
    buf = io.StringIO()
    w = csv.writer(buf, delimiter=delim, lineterminator="\n")
    w.writerow(header)
    w.writerows(rows)
    return buf.getvalue()


def _G_xesc(s: str) -> str:
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")


def _G_plain(d: Decimal) -> str:
    if d == 0:
        return "0"
    s = format(d.normalize(), "f")
    return s.rstrip("0").rstrip(".") if "." in s else s


def _G_in_force(adoptions: list[tuple], start: date) -> str:
    best = None
    for _aid, sheet, status, off in adoptions:
        eff = start + timedelta(days=off)
        if status == "ADOPTED" and eff <= start and (best is None or eff > best[0]):
            best = (eff, sheet)
    return best[1]


# --------------------------------------------------------------------------- xlsx
def _G_col(i: int) -> str:
    s = ""
    i += 1
    while i:
        i, r = divmod(i - 1, 26)
        s = chr(65 + r) + s
    return s


def _G_xlsx(path: Path, sheets: list[tuple[str, list[list[object]], bool]], file_order: list[int], rng: random.Random) -> None:
    strings: list[str] = []
    index: dict[str, int] = {}

    def sidx(s: str) -> int:
        if s not in index:
            index[s] = len(strings)
            strings.append(s)
        return index[s]

    sheet_xml: list[str] = []
    for _, rows, _hidden in sheets:
        out = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
               '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>']
        for r, row in enumerate(rows, 1):
            cells = []
            for c, val in enumerate(row):
                if val is None or val == "":
                    continue
                ref = f"{_G_col(c)}{r}"
                if isinstance(val, (Decimal, int)) and not isinstance(val, bool):
                    cells.append(f'<c r="{ref}"><v>{val}</v></c>')
                elif rng.random() < 0.12:
                    cells.append(f'<c r="{ref}" t="inlineStr"><is><t>{_G_xesc(str(val))}</t></is></c>')
                else:
                    cells.append(f'<c r="{ref}" t="s"><v>{sidx(str(val))}</v></c>')
            out.append(f'<row r="{r}">' + "".join(cells) + "</row>")
        out.append("</sheetData></worksheet>")
        sheet_xml.append("".join(out))
    n = len(sheets)
    ct = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
          '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">',
          '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>',
          '<Default Extension="xml" ContentType="application/xml"/>',
          '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>',
          '<Override PartName="/xl/sharedStrings.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml"/>',
          '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>']
    for k in range(n):
        ct.append(f'<Override PartName="/xl/worksheets/sheet{k + 1}.xml" '
                  'ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>')
    ct.append("</Types>")
    wb = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
          '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
          'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
          '<workbookPr date1904="1" defaultThemeVersion="164011"/><sheets>']
    rels = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">']
    for k, (name, _, hidden) in enumerate(sheets):
        st = ' state="hidden"' if hidden else ""
        wb.append(f'<sheet name="{_G_xesc(name)}" sheetId="{k + 1}"{st} r:id="rId{k + 1}"/>')
        rels.append(f'<Relationship Id="rId{k + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet{file_order[k]}.xml"/>')
    wb.append("</sheets></workbook>")
    rels.append(f'<Relationship Id="rId{n + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings" Target="sharedStrings.xml"/>')
    rels.append(f'<Relationship Id="rId{n + 2}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>')
    rels.append("</Relationships>")
    sst = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
           f'<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="{len(strings)}" uniqueCount="{len(strings)}">']
    sst += [f'<si><t xml:space="preserve">{_G_xesc(s)}</t></si>' for s in strings]
    sst.append("</sst>")
    root_rels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                 '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                 '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
                 '</Relationships>')
    styles = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
              '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
              '<fonts count="1"><font><sz val="11"/><name val="Calibri"/></font></fonts>'
              '<fills count="1"><fill><patternFill patternType="none"/></fill></fills>'
              '<borders count="1"><border/></borders>'
              '<cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="1"><xf/></cellXfs>'
              '</styleSheet>')
    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as z:
        def put(name: str, data: str) -> None:
            info = zipfile.ZipInfo(name, date_time=(2026, 9, 29, 9, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            z.writestr(info, data)
        put("[Content_Types].xml", "".join(ct))
        put("_rels/.rels", root_rels)
        put("xl/workbook.xml", "".join(wb))
        put("xl/_rels/workbook.xml.rels", "".join(rels))
        put("xl/sharedStrings.xml", "".join(sst))
        put("xl/styles.xml", styles)
        for k in range(n):
            put(f"xl/worksheets/sheet{file_order[k]}.xml", sheet_xml[k])


# --------------------------------------------------------------------------- pdf
def _G_pesc(s: str) -> str:
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def _G_ptext(cell: str, rng: random.Random) -> str:
    r = rng.random()
    if r < 0.4 or len(cell) < 2:
        return f"({_G_pesc(cell)}) Tj"
    if r < 0.7:
        hx = cell.encode("latin-1").hex()
        return f"<{hx.upper() if rng.random() < 0.5 else hx}> Tj"
    cuts = sorted(rng.sample(range(1, len(cell)), min(len(cell) - 1, rng.randint(1, 2))))
    parts, last = [], 0
    for cut in cuts + [len(cell)]:
        parts.append(cell[last:cut])
        last = cut
    body = []
    for k, frag in enumerate(parts):
        if k:
            body.append(str(rng.choice([-rng.randint(5, 60), rng.randint(1, 30)])))
        body.append(f"({_G_pesc(frag)})" if rng.random() < 0.6 else f"<{frag.encode('latin-1').hex()}>")
    return "[" + " ".join(body) + "] TJ"


def _G_pdf(path: Path, pages: list[list[list[str]]], rng: random.Random) -> None:
    n = len(pages)
    slots = list(range(4, 4 + 2 * n))
    rng.shuffle(slots)
    page_obj, cont_obj = slots[:n], slots[n:]
    objs: dict[int, bytes] = {1: b"<< /Type /Catalog /Pages 2 0 R >>",
                              2: f"<< /Type /Pages /Kids [{' '.join(f'{i} 0 R' for i in page_obj)}] /Count {n} >>".encode(),
                              3: b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"}
    for p, rows in enumerate(pages):
        items = []
        y = 806
        for cells in rows + [[f"Bulletin Q4-26 page {p + 1} of {n}"]]:
            if cells[0].startswith("Bulletin Q4-26 page"):
                y = 24
            for k, cell in enumerate(cells):
                items.append(f"BT /F1 8 Tf 1 0 0 1 {40 + 92 * k} {y} Tm {_G_ptext(cell, rng)} ET")
            y -= 11
        rng.shuffle(items)
        raw = "".join(it + rng.choice(["\n", " ", "\n"]) for it in items).encode("latin-1")
        comp = zlib.compress(raw, 9)
        objs[page_obj[p]] = (f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 3 0 R >> >> "
                             f"/Contents {cont_obj[p]} 0 R >>").encode()
        objs[cont_obj[p]] = f"<< /Length {len(comp)} /Filter /FlateDecode >>\nstream\n".encode() + comp + b"\nendstream"
    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = []
    for i in range(1, len(objs) + 1):
        offsets.append(len(out))
        out += f"{i} 0 obj\n".encode() + objs[i] + b"\nendobj\n"
    xref = len(out)
    out += f"xref\n0 {len(objs) + 1}\n0000000000 65535 f \n".encode()
    for off in offsets:
        out += f"{off:010d} 00000 n \n".encode()
    out += f"trailer\n<< /Size {len(objs) + 1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n".encode()
    path.write_bytes(bytes(out))


def _G_paginate(rows: list[list[str]], first: int, rest: int, header: list[str] | None, cont: str | None) -> list[list[list[str]]]:
    pages = [rows[:first]]
    tail = rows[first:]
    while tail:
        head = ([[cont]] if cont else []) + ([header] if header else [])
        pages.append(head + tail[:rest])
        tail = tail[rest:]
    return pages


# --------------------------------------------------------------------------- optimisation (author side)
def _G_curve(r: list[Decimal], hours: int, unit: int, kmax: int, sc: Decimal, nd: Decimal) -> list[Decimal]:
    out = []
    for k in range(kmax + 1):
        c = Decimal(k * unit)
        out.append(sc * sum((x if x < c else c) for x in r) - nd * hours * c)
    return out


def _G_greedy(pools: dict, cap: int) -> dict:
    """Published optimiser: node-by-node marginal saving, no family caps, no minimums, no memory."""
    k = {p: 0 for p in pools}
    used = 0
    while used < cap:
        best = None
        for p, v in pools.items():
            if k[p] + 1 < len(v["curve"]):
                gain = v["curve"][k[p] + 1] - v["curve"][k[p]]
                if gain > 0 and (best is None or gain > best[0]):
                    best = (gain, p)
        if best is None:
            break
        k[best[1]] += 1
        used += 1
    return k


# --------------------------------------------------------------------------- model
def _Ggenerate(data_dir: Path, seed: int, cfg: dict | None = None) -> None:
    c = dict(_GDEFAULT_CFG)
    c.update(cfg or {})
    data_dir.mkdir(parents=True, exist_ok=True)
    for stale in data_dir.iterdir():
        if stale.is_file() and stale.suffix != ".md":
            stale.unlink()
    S: dict = {"c": c, "rng": random.Random(seed), "seed": seed, "dir": data_dir}
    btz = _G_tz(c["billing"])
    w0l = datetime.fromisoformat(c["w0_local"])
    w1l = datetime.fromisoformat(c["w1_local"])
    S.update(btz=btz, w0l=w0l, w1l=w1l, w0=w0l.replace(tzinfo=btz).astimezone(_GUTC), w1=w1l.replace(tzinfo=btz).astimezone(_GUTC),
             horizon=datetime.fromisoformat(c["horizon"]).replace(tzinfo=_GUTC))
    S["nh"] = int((S["w1"] - S["w0"]) / _GHOUR)
    S["inforce"] = _G_in_force(c["adoptions"], w0l.date())
    _G_g_model(S)
    _G_g_journal(S)
    _G_g_shards(S)
    _G_g_calibrate(S)
    _G_g_reference_files(S)
    _G_g_decoys(S)
    _G_g_workbook(S)
    _G_g_bulletin(S)
    _G_g_profile(S)


def _G_uid(S: dict, prefix: str, digits: int, used: set) -> str:
    rng = S["rng"]
    while True:
        v = prefix + "".join(rng.choice("0123456789") for _ in range(digits))
        if v not in used:
            used.add(v)
            return v


def _G_g_model(S: dict) -> None:
    c, rng = S["c"], S["rng"]
    W0, W1, NH, w0l = S["w0"], S["w1"], S["nh"], S["w0l"]
    ORG, OTHER, IN_SCOPE = c["org"], c["other_orgs"], c["in_scope"]
    cluster_codes = [x for x, _, _, _ in _GCLUSTERS]
    alias_of = {x: al for x, _, _, al in _GCLUSTERS}

    def ctok(code: str) -> str:
        r = rng.random()
        if r < 0.55:
            return code
        if r < 0.62:
            return rng.choice([code.lower(), " " + code, code + " "])
        return rng.choice(alias_of[code])

    S["ctok"] = ctok
    fam_codes = [f for f, *_ in _GFAMILIES]
    t_used: set[str] = set()
    tmpl_fam: dict[str, str] = {}

    def new_tid(f: str) -> str:
        while True:
            tid = f"{f.upper()}-{rng.randint(100, 9999):04d}"
            if tid not in t_used:
                t_used.add(tid)
                return tid

    for f in fam_codes:
        for _ in range(16):
            tmpl_fam[new_tid(f)] = f if rng.random() > 0.16 else rng.choice([g for g in fam_codes if g != f])
    for f in fam_codes:
        while sum(1 for h in tmpl_fam.values() if h == f) < 6:
            tmpl_fam[new_tid(f)] = f
    S["tmpl_fam"] = tmpl_fam
    S["tmpl_by_fam"] = {f: sorted(t for t, h in tmpl_fam.items() if h == f) for f in fam_codes}

    factor: dict[str, Decimal] = {}
    size_rows: list[list[object]] = [["engine", "normalized_factor", "note"]]
    for f, _, _, _, top in _GFAMILIES:
        for s, v in _GSIZES:
            val = Decimal(top) if v is None else Decimal(v)
            factor[f"{f}.{s}"] = val
            cell: object = int(val) if val == val.to_integral_value() and rng.random() < 0.6 else f" {_G_plain(val)} "
            size_rows.append([f"{f}.{s}", cell, "family specific" if v is None else ""])
    S["factor"], S["size_rows"] = factor, size_rows

    # ---------------------------------------------------------------- projects
    used: set[str] = set()
    projs: dict[str, dict] = {}
    productive, devp, others, closed_before, closed_after = [], [], [], [], []
    for _ in range(262):
        a = _G_uid(S, "PJ", 8, used)
        projs[a] = {"org": ORG, "team": rng.choice(_GTEAMS), "status": "ACTIVE", "closed": None, "tier": "prod"}
        productive.append(a)
    for _ in range(214):
        a = _G_uid(S, "PJ", 8, used)
        projs[a] = {"org": ORG, "team": rng.choice(_GTEAMS), "status": rng.choice(["ACTIVE", "ACTIVE", "DORMANT"]), "closed": None, "tier": "dev"}
        devp.append(a)
    for _ in range(205):
        a = _G_uid(S, "PJ", 8, used)
        projs[a] = {"org": rng.choice(OTHER), "team": rng.choice(_GTEAMS), "status": "ACTIVE", "closed": None, "tier": "prod"}
        others.append(a)
    for _ in range(22):
        a = _G_uid(S, "PJ", 8, used)
        projs[a] = {"org": ORG, "team": rng.choice(_GTEAMS), "status": "CLOSED",
                    "closed": w0l.date() - timedelta(days=rng.randint(1, 104)), "tier": "prod"}
        closed_before.append(a)
    for _ in range(14):
        a = _G_uid(S, "PJ", 8, used)
        projs[a] = {"org": ORG, "team": rng.choice(_GTEAMS), "status": "CLOSED",
                    "closed": w0l.date() + timedelta(days=rng.randint(0, 30)), "tier": "prod"}
        closed_after.append(a)
        productive.append(a)
    unknown = [_G_uid(S, "PJ", 8, used) for _ in range(30)]

    # ---------------------------------------------------------------- dated merge ledger
    merges: dict[str, tuple[str, date]] = {}
    m_used: set[str] = set()
    days = NH // 24

    def mdate() -> date:
        if rng.random() < c["merge_window_frac"]:
            return w0l.date() + timedelta(days=rng.randint(1, days + 3))
        return w0l.date() - timedelta(days=rng.randint(2, 600))

    layer1 = []
    targets = rng.sample(productive, 120) + rng.sample(devp, 30) + rng.sample(others, 20) + rng.sample(unknown, 4)
    for t in targets:
        a = _G_uid(S, "MG", 7, m_used)
        merges[a] = (t, mdate())
        layer1.append(a)
    layer2 = []
    for t in rng.sample(layer1, 66):
        a = _G_uid(S, "MG", 7, m_used)
        merges[a] = (t, mdate())
        layer2.append(a)
    for t in rng.sample(layer2, 31):
        a = _G_uid(S, "MG", 7, m_used)
        merges[a] = (t, mdate())
    cyc_members: list[list[str]] = []
    free = [p for p in productive if p not in closed_after]
    for length in c["cycles"]:
        ring = rng.sample(free, length)
        for p in ring:
            free.remove(p)
        ds = sorted(rng.sample(range(1, days - 1), length))
        for k, p in enumerate(ring):
            merges[p] = (ring[(k + 1) % length], w0l.date() + timedelta(days=ds[k]))
        cyc_members.append(ring)
    # merged-away MG projects are real registered projects until their merge date
    for a, (t, d) in merges.items():
        if not a.startswith("MG"):
            continue
        base = projs.get(t)
        org = base["org"] if base and rng.random() > 0.12 else rng.choice([ORG] + OTHER)
        if d < w0l.date() or rng.random() < 0.4:
            projs[a] = {"org": org, "team": rng.choice(_GTEAMS), "status": "CLOSED", "closed": d, "tier": "prod"}
        else:
            projs[a] = {"org": org, "team": rng.choice(_GTEAMS), "status": "ACTIVE", "closed": None, "tier": "prod"}
    S.update(projs=projs, productive=productive, devp=devp, others=others, closed_before=closed_before,
             closed_after=closed_after, unknown=unknown, merges=merges, cyc_members=cyc_members)

    def eff_instant(d: date) -> datetime:
        return datetime(d.year, d.month, d.day, tzinfo=S["btz"]).astimezone(_GUTC)

    S["eff_instant"] = eff_instant

    def resolve(tok: str, at: datetime) -> str:
        seen = [tok]
        while tok in merges and eff_instant(merges[tok][1]) <= at:
            tok = merges[tok][0]
            if tok in seen:
                return min(seen[seen.index(tok):])
            seen.append(tok)
        return tok

    S["resolve"] = resolve
    aliases_for: dict[str, list[str]] = {}
    for a in sorted(merges):
        aliases_for.setdefault(resolve(a, S["w1"] + timedelta(days=30)), []).append(a)

    def ptok(p: str) -> str:
        al = aliases_for.get(p)
        t = rng.choice(al) if al and rng.random() < 0.3 else p
        if rng.random() < 0.05:
            t = rng.choice([t.lower(), " " + t, t + " "])
        return t

    S["ptok"] = ptok

    # ---------------------------------------------------------------- pools and query lines
    elig_live = {f: e for f, _, _, e, _ in _GFAMILIES}
    pool_clusters: dict[str, list[str]] = {}
    outside = [r for r in cluster_codes if r not in IN_SCOPE]
    for f in fam_codes:
        k = rng.randint(4, 6)
        regs = rng.sample(IN_SCOPE, min(len(IN_SCOPE), k - 1)) + rng.sample(outside, 1)
        pool_clusters[f] = sorted(set(regs))
    pools = [(f, r) for f in fam_codes for r in pool_clusters[f]]
    S["pools"] = pools
    line_used: set[str] = set()
    lines: list[dict] = []
    S["line_used"] = line_used

    def add_line(t: datetime, ptk: str, cl: str, tmpl: str, size: str, qty: Decimal, opt: str, tag: str) -> dict:
        ln = {"lid": _G_uid(S, "QL", 10, line_used), "t": t, "acct": ptk, "cl": cl, "rtok": ctok(cl), "tmpl": tmpl,
              "size": size, "qty": qty, "opt": opt, "status": "F", "rev": rng.randint(1, 4), "tag": tag}
        lines.append(ln)
        return ln

    pool_projects: dict[tuple[str, str], list[str]] = {}
    for p in pools:
        pool_projects[p] = rng.sample(productive, rng.randint(3, 7))
    S["pool_projects"] = pool_projects
    for (f, r) in pools:
        cand = elig_live[f] and r in IN_SCOPE
        level = Decimal(rng.choice([24, 40, 64, 96, 128, 160, 200])) * Decimal(rng.choice(["0.8", "1", "1.25", "1.5"]))
        amp = rng.uniform(0.3, 1.0)
        phase = rng.randint(0, 23)
        density = c["core_density"] if cand else 0.28
        sizes = rng.sample(_GUSE_SIZES, 5)
        tpls = S["tmpl_by_fam"][f]
        for h in range(-14, NH + 14):
            if rng.random() > density:
                continue
            start = W0 + _GHOUR * h
            loc = start.astimezone(_GCLUSTER_OFF[r])
            wk = 0.8 if loc.weekday() >= 5 else 1.0
            target = float(level) * wk * (1 + amp * (_GDIURNAL[(loc.hour + phase) % 24] - 1)) * rng.uniform(0.85, 1.15)
            if rng.random() < 0.02:
                target *= rng.uniform(1.6, 2.4)
            n = rng.choices([1, 2, 3], [45, 40, 15])[0]
            for _ in range(n):
                share = target / n * rng.uniform(0.7, 1.3)
                size = rng.choice(sizes)
                qty = Decimal(str(max(0.01, round(share / float(factor[f"{f}.{size}"]), 2))))
                if qty > 400:
                    qty = Decimal("400")
                t = start + timedelta(minutes=30) if rng.random() < 0.82 else start + timedelta(seconds=rng.randint(0, 3599))
                opt = "C" if rng.random() < 0.18 else "S"
                add_line(t, ptok(rng.choice(pool_projects[(f, r)])), r, rng.choice(tpls), size, qty, opt, "core")
            if rng.random() < 0.04:
                add_line(start + timedelta(minutes=30), ptok(rng.choice(pool_projects[(f, r)])), r, rng.choice(tpls),
                         rng.choice(sizes), Decimal(str(round(rng.uniform(0.5, 12), 2))), "B", "batch")

    def in_window() -> datetime:
        return W0 + timedelta(seconds=rng.randint(0, NH * 3600 - 1))

    def noise(pool_ids: list[str], tag: str, n: int, tok: bool = True) -> None:
        for _ in range(n):
            f, r = rng.choice(pools)
            add_line(in_window(), ptok(rng.choice(pool_ids)) if tok else rng.choice(pool_ids), r, rng.choice(S["tmpl_by_fam"][f]),
                     rng.choice(_GUSE_SIZES), Decimal(str(round(rng.uniform(0.25, 30), 2))), rng.choice(["S", "S", "C"]), tag)

    noise(others, "other_org", 620)
    noise(devp, "dev", 700)
    noise(unknown, "unknown", 120, tok=False)
    noise(closed_before, "closed", 160)
    noise(closed_after, "closed_after", 120)
    cand_pools = [p for p in pools if elig_live[p[0]] and p[1] in IN_SCOPE]
    for _ in range(40):
        f, r = rng.choice(cand_pools)
        pp = pool_projects[(f, r)]
        add_line(W0, ptok(rng.choice(pp)), r, rng.choice(S["tmpl_by_fam"][f]), "l", Decimal(str(round(rng.uniform(1, 9), 2))), "S", "at_w0")
        add_line(W1, ptok(rng.choice(pp)), r, rng.choice(S["tmpl_by_fam"][f]), "l", Decimal(str(round(rng.uniform(1, 9), 2))), "S", "at_w1")
        add_line(W0 - timedelta(seconds=rng.randint(1, 1800)), ptok(rng.choice(pp)), r, rng.choice(S["tmpl_by_fam"][f]), "xl",
                 Decimal(str(round(rng.uniform(1, 9), 2))), "S", "pre_w0")
        add_line(W1 - timedelta(seconds=rng.randint(1, 1800)), ptok(rng.choice(pp)), r, rng.choice(S["tmpl_by_fam"][f]), "xl",
                 Decimal(str(round(rng.uniform(1, 9), 2))), "S", "pre_w1")
    # queries placed exactly on, and one second before, the instant a dated merge takes effect
    edge = [a for a in sorted(merges) if W0 < eff_instant(merges[a][1]) < W1]
    for a in rng.sample(edge, min(len(edge), c["merge_edges"])):
        f, r = rng.choice(cand_pools)
        at = eff_instant(merges[a][1])
        for t in (at, at - timedelta(seconds=1)):
            add_line(t, a if rng.random() < 0.8 else a.lower(), r, rng.choice(S["tmpl_by_fam"][f]), rng.choice(["xl", "2xl", "3xl"]),
                     Decimal(str(round(rng.uniform(4, 30), 2))), "S", "merge_edge")
    for ring in cyc_members:
        for p in ring:
            f, r = rng.choice(cand_pools)
            for _ in range(10):
                add_line(in_window(), p, r, rng.choice(S["tmpl_by_fam"][f]), rng.choice(["xl", "2xl"]),
                         Decimal(str(round(rng.uniform(4, 30), 2))), "S", "cycle")
    rng.shuffle(lines)
    S["lines"] = lines
    S["cand_pools"] = cand_pools
    S["in_window"] = in_window
    S["elig_live"] = elig_live

    # ---------------------------------------------------------------- outage windows
    W0_LOCAL, W1_LOCAL = S["w0l"], S["w1l"]
    outages = []
    for r in IN_SCOPE:
        for _ in range(rng.randint(1, 3)):
            s = rng.randint(0, NH - 9) if rng.random() < 0.85 else rng.choice([0, NH - 4])
            a0 = W0_LOCAL + _GHOUR * s
            a1 = min(W1_LOCAL, a0 + _GHOUR * rng.randint(2, 8))
            outages.append((r, a0, a1))
    for r in rng.sample(outside, 2):
        a0 = W0_LOCAL + _GHOUR * rng.randint(0, NH - 9)
        outages.append((r, a0, a0 + _GHOUR * 6))
    rng.shuffle(outages)
    S["outages"] = outages


def _G_g_journal(S: dict) -> None:
    c, rng = S["c"], S["rng"]
    lines, productive, others, devp = S["lines"], S["productive"], S["others"], S["devp"]
    ptok, ctok, line_used = S["ptok"], S["ctok"], S["line_used"]
    ops = []
    core_lines = [ln for ln in lines if ln["tag"] == "core"]
    S["core_lines"] = core_lines
    for ln in rng.sample(core_lines, c["journal_lines"]):
        kind = rng.choices(["VOID", "SETQTY", "MOVE", "ADDNEW", "ADDDUP", "MISS", "VOIDADD"], [16, 30, 14, 16, 7, 7, 10])[0]
        if kind == "VOID":
            ops.append({"op": "VOID", "query_id": ln["lid"]})
        elif kind == "SETQTY":
            ops.append({"op": "SETQTY", "query_id": ln["lid"],
                        "quantity_gib": str(Decimal(str(round(float(ln["qty"]) * rng.uniform(0.3, 1.8), 2))).max(Decimal("0.01")))})
        elif kind == "MOVE":
            ops.append({"op": "MOVE", "query_id": ln["lid"], "project": ptok(rng.choice(productive + others[:20] + devp[:20]))})
        elif kind in ("ADDNEW", "ADDDUP", "VOIDADD"):
            if kind == "VOIDADD":
                ops.append({"op": "VOID", "query_id": ln["lid"]})
            lid = ln["lid"] if kind != "ADDNEW" else _G_uid(S, "QL9", 8, line_used)
            t = ln["t"] + timedelta(hours=rng.randint(-3, 3)) if kind != "ADDNEW" else S["in_window"]()
            src = ln["acct"].strip().upper()
            ops.append({"op": "ADD", "query_id": lid, "usage_start_utc": _G_iso_z(t),
                        "project": ptok(src if src in S["projs"] else rng.choice(productive)),
                        "cluster": ctok(ln["cl"]).strip(), "template": ln["tmpl"], "size": ln["size"],
                        "quantity_gib": str(Decimal(str(round(rng.uniform(0.5, 40), 2)))), "option": rng.choice(["S", "S", "C", "B"])})
        else:
            ops.append({"op": rng.choice(["VOID", "SETQTY", "MOVE"]), "query_id": _G_uid(S, "QL", 10, line_used),
                        "quantity_gib": "3.5", "project": rng.choice(productive)})
    tids = sorted(S["tmpl_fam"])
    for ln in rng.sample(core_lines, c["retag"]):
        if rng.random() < 0.15:
            ops.append({"op": "VOID", "query_id": ln["lid"]})
        ops.append({"op": "RETAG", "query_id": ln["lid"], "template": rng.choice(tids)})
    for _ in range(c["retag"] // 8):
        ops.append({"op": "RETAG", "query_id": _G_uid(S, "QL", 10, line_used), "template": rng.choice(tids)})
    for o, s in zip(ops, sorted(rng.sample(range(100000, 999999), len(ops)))):
        o["seq"] = s
        o["status"] = rng.choices(["POSTED", "posted", "Posted", "PENDING", "REJECTED"], [60, 10, 8, 12, 10])[0]
        if o["op"] == "VOID":
            o.pop("quantity_gib", None)
            o.pop("project", None)
        elif o["op"] == "SETQTY":
            o.pop("project", None)
        elif o["op"] == "MOVE":
            o.pop("quantity_gib", None)
        o["journal"] = "jsonl" if rng.random() < 0.55 else "xml"
    S["ops"] = ops


def _G_g_shards(S: dict) -> None:
    c, rng, data_dir = S["c"], S["rng"], S["dir"]
    btz = S["btz"]
    names_used: set[str] = set()
    shard_files: list[tuple[str, str]] = []

    def stem_name(ext: str) -> str:
        while True:
            stem = rng.choice(["qx", "lg", "sc", "wh", "tq", "ev", "rn", "pm"]) + "_" + \
                "".join(rng.choice("abcdefghjkmnpqrstuvwxyz23456789") for _ in range(4)) + "_" + str(rng.randint(10, 99))
            fn = f"{stem}.{ext}"
            if fn not in names_used:
                names_used.add(fn)
                return fn

    for k in range(c["n_shards"]):
        layout = _GLAYOUTS[k % 16]
        shard_files.append((stem_name(_GEXT[layout]), layout))
    names = [fn for fn, _ in shard_files]
    local_files = [fn for fn, lay in shard_files if lay in _GLOCAL_LAYOUTS]
    rows_by: dict[str, list[dict]] = {fn: [] for fn in names}
    by_lid: dict[str, dict] = {}
    for ln in S["lines"]:
        home = rng.choice(local_files) if ln["tag"] in ("at_w0", "at_w1", "pre_w0", "pre_w1") and rng.random() < 0.5 else rng.choice(names)
        win = dict(ln, file=home)
        r = rng.random()
        if r < 0.10:
            dup = dict(ln)
            if rng.random() < 0.5:
                dup["rev"] = max(0, ln["rev"] - rng.randint(1, 3))
                dup["qty"] = Decimal(str(round(float(ln["qty"]) * rng.uniform(0.4, 1.6), 2))).max(Decimal("0.01"))
                if rng.random() < 0.3:
                    dup["status"] = "V"
            else:
                win["rev"] = ln["rev"] + rng.randint(1, 3)
                win["qty"] = Decimal(str(round(float(ln["qty"]) * rng.uniform(0.6, 1.4), 2))).max(Decimal("0.01"))
                dup["rev"] = ln["rev"]
                if rng.random() < 0.25:
                    win["status"] = "V"
            dup["file"] = home if rng.random() < 0.12 else rng.choice([n for n in names if n != home])
            rows_by[dup["file"]].append(dup)
        elif r < 0.125:
            win["status"] = "V"
        rows_by[home].append(win)
        by_lid[ln["lid"]] = win
    for fn in names:
        rng.shuffle(rows_by[fn])
    S["by_lid"] = by_lid

    catalog = []
    for fn, layout in shard_files:
        _G_g_write_shard(S, data_dir / fn, fn, layout, rows_by[fn])
        catalog.append({"file": fn, "layout": layout, "ts_convention": _GTS_CONV[layout], "qty_unit": _GQTY_UNIT[layout],
                        "option_codes": {v: k for k, v in _GOPT_CODES[layout].items()},
                        "status_codes": {v: k for k, v in _GSTATUS_CODES[layout].items()}})
    # feed-shaped exports that the manifest does not list
    for k in range(c["decoy_feeds"]):
        layout = rng.choice(["csv_a", "jsonl_flat", "xml_attr"])
        fn = stem_name(_GEXT[layout])
        stale = [dict(ln, rev=ln["rev"] + 5, qty=(ln["qty"] * Decimal("2")).quantize(Decimal("0.01"))) for ln in rng.sample(S["core_lines"], 300)]
        _G_g_write_shard(S, data_dir / fn, fn, layout, stale)
    rng.shuffle(catalog)
    _G_write(data_dir / "ingest_manifest_r7.json", json.dumps({
        "manifest_version": "7.1",
        "note": "Only files listed under shards are query-log feeds. option_codes map each layout's cache option code to S (scanned on the warehouse), C (served from an existing cache reservation) or B (batch, preemptible); status_codes map to F (final) or V (voided). qty_unit names the unit of the scanned-volume column.",
        "shards": catalog}, indent=2) + "\n")
    cache_rows = [dict(ln, rev=ln["rev"] + 7, qty=(ln["qty"] * Decimal("1.5")).quantize(Decimal("0.01"))) for ln in rng.sample(S["core_lines"], 280)]
    _G_write(data_dir / "scan_rollup_cache_03.jsonl", "".join(json.dumps(
        {"qid": r["lid"], "start": _G_iso_z(r["t"]), "proj": r["acct"], "clu": r["rtok"], "tpl": r["tmpl"], "wh": r["size"], "gib": str(r["qty"]),
         "opt": _GOPT_CODES["jsonl_flat"][r["opt"]], "st": "final", "rev": r["rev"]}) + "\n" for r in cache_rows))
    del btz


def _G_g_write_shard(S: dict, path: Path, fn: str, layout: str, rows: list[dict]) -> None:
    rng, btz = S["rng"], S["btz"]
    oc, sc = _GOPT_CODES[layout], _GSTATUS_CODES[layout]

    def idt(t: str) -> str:
        if rng.random() < 0.06:
            return rng.choice([t.lower(), " " + t, t + "  "])
        return t

    def ttok(t: str) -> str:
        return rng.choice([t.lower(), " " + t]) if rng.random() < 0.05 else t

    def ztok(s: str) -> str:
        return s.upper() if rng.random() < 0.06 else s

    def offs(t: datetime) -> str:
        off = rng.choice([0, -300, 330, -420, 540, 60, 345, 570])
        return t.astimezone(timezone(timedelta(minutes=off))).isoformat()

    def wall_cluster(r: dict) -> str:
        return r["t"].astimezone(_GCLUSTER_OFF[r["cl"]]).strftime("%Y-%m-%d %H:%M:%S")

    def wall_billing(r: dict) -> str:
        return r["t"].astimezone(btz).strftime("%Y-%m-%d %H:%M:%S")

    def q_g(r: dict) -> str:
        v = r["qty"]
        return str(v) if rng.random() < 0.5 else _G_plain(v)

    def q_mib(r: dict) -> Decimal:
        return r["qty"] * 1024

    def q_kib(r: dict) -> str:
        return _G_plain(r["qty"] * 1048576)

    def jnum(d: Decimal) -> float | int:
        return int(d) if d == d.to_integral_value() else float(d)

    def ep(r: dict) -> int:
        return int(r["t"].timestamp())

    if layout == "jsonl_flat":
        _G_write(path, "".join(json.dumps({"qid": idt(r["lid"]), "start": _G_iso_z(r["t"]), "proj": r["acct"], "clu": r["rtok"],
                                         "tpl": ttok(r["tmpl"]), "wh": ztok(r["size"]), "gib": q_g(r), "opt": oc[r["opt"]],
                                         "st": sc[r["status"]], "rev": r["rev"]}) + "\n" for r in rows))
    elif layout == "ndjson_nested":
        _G_write(path, "".join(json.dumps({"query": {"id": idt(r["lid"]), "rev": r["rev"]}, "scan": {"start": ep(r), "mib": jnum(q_mib(r))},
                                         "ctx": {"project": r["acct"], "cluster": r["rtok"], "template": ttok(r["tmpl"]), "size": ztok(r["size"])},
                                         "bill": {"option": oc[r["opt"]], "status": sc[r["status"]]}}, separators=(",", ":")) + "\n" for r in rows))
    elif layout == "csv_a":
        _G_write(path, _G_csv_text(["query_id", "started_utc", "project_id", "cluster", "template_id", "wh_size", "scanned_gib", "cache_option", "query_status", "revision"],
                               [[idt(r["lid"]), _G_iso_z(r["t"]), r["acct"], r["rtok"], ttok(r["tmpl"]), ztok(r["size"]), q_g(r), oc[r["opt"]], sc[r["status"]], r["rev"]] for r in rows]))
    elif layout == "tsv_epoch":
        _G_write(path, _G_csv_text(["rev", "epoch_s", "proj", "clu", "tpl", "wh", "scan_kib", "opt", "st", "id"],
                               [[r["rev"], ep(r), r["acct"], r["rtok"], ttok(r["tmpl"]), ztok(r["size"]), q_kib(r), oc[r["opt"]], sc[r["status"]], idt(r["lid"])] for r in rows], "\t"))
    elif layout == "psv_local":
        _G_write(path, _G_csv_text(["id", "clu", "local_start", "proj", "tpl", "wh", "gib", "opt", "st", "rev"],
                               [[idt(r["lid"]), r["rtok"], wall_cluster(r), r["acct"], ttok(r["tmpl"]), ztok(r["size"]), q_g(r), oc[r["opt"]], sc[r["status"]], r["rev"]] for r in rows], "|"))
    elif layout == "txt_fixed":
        out = ["# query log dump, fixed width (see feed layouts)",
               "# id 1-12 | utc 13-26 | project 27-38 | cluster 39-63 | template 64-73 | size 74-77 | mib 78-89 | opt 90-91 | st 92 | rev 93-95"]
        for r in rows:
            reg = r["rtok"].strip()[:25]
            out.append(f"{idt(r['lid']).strip():<12}{r['t'].astimezone(_GUTC):%Y%m%d%H%M%S}{r['acct'].strip():<12}{reg:<25}"
                       f"{ttok(r['tmpl']).strip():<10}{ztok(r['size']):<4}{_G_plain(q_mib(r)):>12}{oc[r['opt']]:<2}{sc[r['status']]}{r['rev']:03d}")
        _G_write(path, "\n".join(out) + "\n")
    elif layout == "xml_attr":
        body = "".join(f'  <q id="{_G_xesc(idt(r["lid"]))}" t="{offs(r["t"])}" p="{_G_xesc(r["acct"])}" c="{_G_xesc(r["rtok"])}" '
                       f'tp="{_G_xesc(ttok(r["tmpl"]))}" w="{ztok(r["size"])}" g="{q_g(r)}" o="{oc[r["opt"]]}" s="{sc[r["status"]]}" v="{r["rev"]}"/>\n' for r in rows)
        _G_write(path, f'<?xml version="1.0" encoding="UTF-8"?>\n<querylog source="{fn}">\n{body}</querylog>\n')
    elif layout == "yaml_list":
        out = [f"# export {fn}", "feed: warehouse-east", "records:"]
        for r in rows:
            q = rng.choice(['"', "'", ""])
            out += [f"  - id: {q}{idt(r['lid']).strip()}{q}", f"    start: {_G_iso_z(r['t'])}", f"    project: \"{r['acct']}\"",
                    f"    cluster: \"{r['rtok']}\"", f"    template: {ttok(r['tmpl']).strip()}", f"    size: {ztok(r['size'])}",
                    f"    gib: {q_g(r)}", f"    option: {oc[r['opt']]}", f"    status: {sc[r['status']]}", f"    rev: {r['rev']}"]
        _G_write(path, "\n".join(out) + "\n")
    elif layout == "json_array":
        _G_write(path, json.dumps({"export": {"source": fn, "rows": [
            {"queryId": idt(r["lid"]), "epochMillis": ep(r) * 1000, "projectId": r["acct"], "clusterCode": r["rtok"],
             "templateId": ttok(r["tmpl"]), "whSize": ztok(r["size"]), "scannedMib": jnum(q_mib(r)), "option": oc[r["opt"]],
             "status": sc[r["status"]], "revision": r["rev"]} for r in rows]}}, indent=1) + "\n")
    elif layout in ("sqlite_rows", "db_rows"):
        con = sqlite3.connect(path)
        if layout == "sqlite_rows":
            con.execute("CREATE TABLE query_log (query_id TEXT, started_utc TEXT, project_id TEXT, cluster TEXT, template_id TEXT, wh_size TEXT, scanned_gib TEXT, cache_option TEXT, query_status TEXT, revision INTEGER)")
            con.executemany("INSERT INTO query_log VALUES (?,?,?,?,?,?,?,?,?,?)",
                            [(idt(r["lid"]), _G_iso_z(r["t"]), r["acct"], r["rtok"], ttok(r["tmpl"]), ztok(r["size"]), q_g(r), oc[r["opt"]], sc[r["status"]], r["rev"]) for r in rows])
            con.execute("CREATE TABLE export_note (k TEXT, v TEXT)")
            con.executemany("INSERT INTO export_note VALUES (?,?)", [("layout", "sqlite_rows"), ("table", "query_log")])
        else:
            con.execute("CREATE TABLE ql (qid TEXT, ep INTEGER, prj TEXT, clu TEXT, tpl TEXT, wh TEXT, cg INTEGER, oc TEXT, sc TEXT, rv INTEGER)")
            con.executemany("INSERT INTO ql VALUES (?,?,?,?,?,?,?,?,?,?)",
                            [(idt(r["lid"]), ep(r), r["acct"], r["rtok"], ttok(r["tmpl"]), ztok(r["size"]), int(r["qty"] * 100), oc[r["opt"]], sc[r["status"]], r["rev"]) for r in rows])
        con.commit()
        con.close()
    elif layout == "csv_offset":
        _G_write(path, "\ufeff" + _G_csv_text(["cluster", "ts_offset", "project", "template", "size", "kib", "opt", "code", "rev", "query"],
                                          [[r["rtok"], offs(r["t"]), r["acct"], ttok(r["tmpl"]), ztok(r["size"]), q_kib(r), oc[r["opt"]], sc[r["status"]], r["rev"], idt(r["lid"])] for r in rows]))
    elif layout == "xml_elem":
        body = "".join(f"  <query>\n    <id>{_G_xesc(idt(r['lid']))}</id>\n    <epoch>{ep(r)}</epoch>\n    <project>{_G_xesc(r['acct'])}</project>\n"
                       f"    <cluster>{_G_xesc(r['rtok'])}</cluster>\n    <template>{_G_xesc(ttok(r['tmpl']))}</template>\n    <size>{ztok(r['size'])}</size>\n"
                       f"    <gib>{q_g(r)}</gib>\n    <option>{oc[r['opt']]}</option>\n    <status>{sc[r['status']]}</status>\n    <rev>{r['rev']}</rev>\n  </query>\n" for r in rows)
        _G_write(path, f'<?xml version="1.0" encoding="UTF-8"?>\n<batch>\n{body}</batch>\n')
    elif layout == "yml_list":
        out = ["# edge collector sync"]
        for r in rows:
            out += [f"- qid: {idt(r['lid']).strip()}", f"  local: \"{wall_billing(r)}\"", f"  prj: '{r['acct']}'",
                    f"  clu: '{r['rtok']}'", f"  shape: '{ztok(r['size'])}@{ttok(r['tmpl']).strip()}'", f"  gib: {q_g(r)}",
                    f"  o: {oc[r['opt']]}", f"  s: {sc[r['status']]}", f"  rev: {r['rev']}"]
        _G_write(path, "\n".join(out) + "\n")
    elif layout == "json_keyed":
        obj = {}
        for r in rows:
            key = idt(r["lid"])
            while key in obj:
                key = " " + key
            obj[key] = {"ms": ep(r) * 1000, "p": r["acct"], "c": r["rtok"], "t": ttok(r["tmpl"]), "w": ztok(r["size"]),
                        "mib": jnum(q_mib(r)), "o": oc[r["opt"]], "s": sc[r["status"]], "v": r["rev"]}
        _G_write(path, json.dumps(obj, indent=0) + "\n")
    elif layout == "txt_kv":
        out = ["# collector log key=value; cluster names may contain spaces and are quoted"]
        for r in rows:
            out.append(f"query={idt(r['lid']).strip()} at={wall_cluster(r).replace(' ', 'T')} project={r['acct'].strip()} "
                       f"cluster=\"{r['rtok'].strip()}\" template={ttok(r['tmpl']).strip()} size={ztok(r['size'])} gib={q_g(r)} "
                       f"option={oc[r['opt']]} state={sc[r['status']]} rev={r['rev']}")
        _G_write(path, "\n".join(out) + "\n")


def _G_g_calibrate(S: dict) -> None:
    c, rng = S["c"], S["rng"]
    fam_codes = [f for f, *_ in _GFAMILIES]
    cluster_codes = [x for x, _, _, _ in _GCLUSTERS]
    IN_SCOPE, W0, W1, NH = c["in_scope"], S["w0"], S["w1"], S["nh"]

    def ruleset(variant: str) -> dict:
        fams = {}
        for f, _, _, e, _ in _GFAMILIES:
            eligible = e
            if variant == "B" and f in ("tsr", "logs"):
                eligible = not e
            if variant == "D":
                eligible = f not in ("grph", "arch")
            if variant == "E" and f in ("logs", "dash"):
                eligible = not e
            fams[f] = {"eligible": eligible, "node_units": rng.choice([16, 24, 24, 32, 48]),
                       "min_nodes": rng.choice([2, 3, 3, 4]), "family_cap": 0,
                       "growth_pct": rng.choice([0, 3, 4, 6, 8, 9, 12]), "mem_units": rng.choice([1, 2, 2, 3, 4, 5])}
        return {"fams": fams, "cap": 0, "mem": 0}

    rulesets = {_GSHEET_OF_VARIANT[v]: ruleset(v) for v in ("A", "B", "D", "E")}
    S["rulesets"] = rulesets

    # ---------------------------------------------------------------- rates and errata
    cl_mult = {x: Decimal(m) for x, _, m, _ in _GCLUSTERS}
    q4 = Decimal("0.0001")
    r2, r1 = {}, {}
    for f, base, ratio, _, _ in _GFAMILIES:
        for x in cluster_codes:
            sc = (Decimal(base) * cl_mult[x] / 100 * Decimal(str(rng.uniform(0.97, 1.03)))).quantize(q4)
            nd = (sc * Decimal(ratio) * Decimal(str(rng.uniform(0.96, 1.04)))).quantize(q4)
            r2[(f, x)] = [sc, nd]
            r1[(f, x)] = [(sc * Decimal("1.045")).quantize(q4), (sc * Decimal(ratio) * Decimal("0.93")).quantize(q4)]
    elig_cells = [(f, x) for f in fam_codes for x in IN_SCOPE if S["elig_live"][f]]
    picked = rng.sample(elig_cells, 44)
    errata = []
    for i, (f, x) in enumerate(picked):
        fld = rng.choice(["scan_rate_cents", "node_rate_cents"])
        j = 0 if fld == "scan_rate_cents" else 1
        new = (r2[(f, x)][j] * Decimal(str(rng.uniform(0.9, 1.08)))).quantize(q4)
        if new == r2[(f, x)][j]:
            new += q4
        alt = (r2[(f, x)][j] * Decimal(str(rng.uniform(0.8, 0.88)))).quantize(q4)
        status = "IN FORCE" if i < 30 else "RESCINDED"
        errata.append([f, x, fld, new, status])
        if status == "IN FORCE" and i < 8:
            errata.append([f, x, fld, alt, "RESCINDED"])
        elif status == "IN FORCE" and i < 8 + c["errata_pairs"]:
            errata.append([f, x, fld, alt, "IN FORCE"])
    rng.shuffle(errata)
    for k, e in enumerate(errata):
        e.insert(0, f"E1-{101 + k:03d}")
    eff = {k: list(v) for k, v in r2.items()}
    for eid, f, x, fld, new, status in sorted(errata):
        if status == "IN FORCE":
            eff[(f, x)][0 if fld == "scan_rate_cents" else 1] = new
    S.update(r1=r1, r2=r2, errata=errata)

    # ---------------------------------------------------------------- reservations
    HORIZON, pools, pool_projects = S["horizon"], S["pools"], S["pool_projects"]
    inv_used: set[str] = set()
    inventory = []
    for (f, r) in pools:
        for _ in range(rng.choices([1, 2, 3, 4], [25, 35, 25, 15])[0]):
            end = HORIZON + timedelta(days=rng.randint(-120, 400), hours=rng.randint(0, 23))
            if rng.random() < 0.04:
                end = HORIZON
            inventory.append({"id": _G_uid(S, "RSV-", 6, inv_used), "f": f, "r": r, "owner": rng.choice(pool_projects[(f, r)]),
                              "units": Decimal(rng.choice([2, 4, 4, 6, 8, 12, 16])) * Decimal(rng.choice(["1", "1.5", "0.5"])),
                              "start": W0 - timedelta(days=rng.randint(30, 700)), "end": end,
                              "state": rng.choices(["ACTIVE", "QUEUED", "RETIRED"], [78, 10, 12])[0]})
    for _ in range(40):
        f, r = rng.choice(pools)
        inventory.append({"id": _G_uid(S, "RSV-", 6, inv_used), "f": f, "r": r, "owner": rng.choice(S["others"] + S["devp"]),
                          "units": Decimal(rng.choice([8, 16, 32])), "start": W0 - timedelta(days=rng.randint(30, 400)),
                          "end": HORIZON + timedelta(days=rng.randint(10, 300)), "state": "ACTIVE"})
    rng.shuffle(inventory)
    inv_rulings = []
    for x in rng.sample(inventory, 52):
        if rng.random() < 0.5:
            inv_rulings.append((x["id"], "CANCELLED", "-"))
        else:
            inv_rulings.append((x["id"], "EXTENDED", _G_iso_z(x["end"] + timedelta(days=rng.randint(-200, 200)))))
    rng.shuffle(inv_rulings)
    S.update(inventory=inventory, inv_rulings=inv_rulings)

    # ---------------------------------------------------------------- calibration of limits (author side)
    outages, w0l, projs, factor = S["outages"], S["w0l"], S["projs"], S["factor"]
    ORG = c["org"]

    def in_out(cl: str, t_local: datetime) -> bool:
        return any(r == cl and a0 <= t_local < a1 for r, a0, a1 in outages)

    def series(rs: dict) -> dict:
        out = {}
        acc: dict[tuple[str, str], dict[int, Decimal]] = {}
        for ln in S["by_lid"].values():
            if ln["status"] == "V" or ln["opt"] == "B" or not (W0 <= ln["t"] < W1):
                continue
            a = S["resolve"](ln["acct"].strip().upper(), ln["t"])
            if a not in projs or projs[a]["org"] != ORG or projs[a]["tier"] == "dev":
                continue
            if projs[a]["status"] == "CLOSED" and projs[a]["closed"] < w0l.date():
                continue
            f = S["tmpl_fam"][ln["tmpl"]]
            if ln["cl"] not in IN_SCOPE or not rs["fams"][f]["eligible"]:
                continue
            h = int((ln["t"] - W0) / _GHOUR)
            if in_out(ln["cl"], w0l + _GHOUR * h):
                continue
            acc.setdefault((f, ln["cl"]), {}).setdefault(h, Decimal(0))
            acc[(f, ln["cl"])][h] += ln["qty"] * factor[f"{f}.{ln['size']}"]
        for (f, r), hs in acc.items():
            valid = [h for h in range(NH) if not in_out(r, w0l + _GHOUR * h)]
            e = sum((x["units"] for x in inventory if x["f"] == f and x["r"] == r and x["state"] == "ACTIVE"
                     and x["owner"] in S["productive"] and x["end"] >= HORIZON), Decimal(0))
            g = rs["fams"][f]["growth_pct"]
            res = [max(Decimal(0), hs.get(h, Decimal(0)) * (100 + g) / 100 - e) for h in valid]
            u = rs["fams"][f]["node_units"]
            kmax = int(max(res) / u) if res else 0
            sc_, nd_ = eff[(f, r)]
            out[(f, r)] = {"curve": _G_curve(res, len(valid), u, kmax, sc_, nd_), "f": f, "r": r}
        return out

    fracs = {"RS-C4A": (0.58, 0.44), "RS-C4B": (0.64, 0.5), "DRAFT_RS-C4C": (0.9, 0.95), "RS-C4D": (0.6, 0.46)}
    for name in ("RS-C4A", "RS-C4B", "DRAFT_RS-C4C", "RS-C4D"):
        rs = rulesets[name]
        frac, mfrac = fracs[name]
        cur = series(rs)
        demand: dict[str, int] = {}
        bestk: dict[str, list[int]] = {}
        cl_dem: dict[str, int] = {}
        for v in cur.values():
            kb = max(range(len(v["curve"])), key=lambda k: v["curve"][k])
            demand[v["f"]] = demand.get(v["f"], 0) + kb
            bestk.setdefault(v["f"], []).append(kb)
            cl_dem[v["r"]] = cl_dem.get(v["r"], 0) + kb
        for f, fam in rs["fams"].items():
            d = demand.get(f, 0)
            fam["family_cap"] = max(fam["min_nodes"] + 2, int(d * rng.uniform(0.6, 1.25)))
            ks = sorted(bestk.get(f, [rng.randint(3, 10)]))
            fam["tier_units"] = fam["node_units"] * (ks[len(ks) // 2] + rng.randint(1, 3))
            fam["tier_discount_pct"] = rng.choice([6, 7, 8, 9, 10, 12, 15])
        rs["cap"] = max(20, int(sum(demand.values()) * frac))
        rs["mem"] = max(30, int(sum(d * rs["fams"][f]["mem_units"] for f, d in demand.items()) * mfrac))
        rs["series"] = cur
        rs["cl_dem"] = cl_dem

    live = rulesets[S["inforce"]]
    lo, hi = c["m1"]
    m1 = {}
    for r in IN_SCOPE:
        m1[r] = max(2, int(live["cl_dem"].get(r, 4) * rng.uniform(lo, hi)))
    missing = rng.sample(IN_SCOPE, c["m1_missing"])
    m0 = {r: max(1, int(m1[r] * rng.uniform(0.35, 0.7))) for r in IN_SCOPE}
    for r in rng.sample([x for x in cluster_codes if x not in IN_SCOPE], 2):
        m1[r] = rng.randint(3, 9)
        m0[r] = rng.randint(1, 4)
    for r in missing:
        m1.pop(r)
    S.update(m1=m1, m0=m0)

    # ---------------------------------------------------------------- faulty published plan
    pub_pools = live["series"]
    draft = rulesets["DRAFT_RS-C4C"]
    faulty = {}
    for p in sorted(pub_pools):
        v = pub_pools[p]
        stretch = Decimal(str(rng.uniform(0.85, 1.25)))
        faulty[p] = {"curve": [x * stretch for x in v["curve"]] + [v["curve"][-1] * stretch - Decimal(1)] * rng.randint(0, 6)}
    ann_cap = int(live["cap"] * 1.35) + 7
    S["ann_cap"] = ann_cap
    pub_k = _G_greedy(faulty, ann_cap)
    pub_rows = []

    def team_lines(pid: str, k: int, units: int, saving: int, teams: list[str]) -> None:
        w = [rng.randint(1, 9) for _ in teams]
        left = saving
        for j, tm in enumerate(teams):
            part = saving * w[j] // sum(w) if j < len(teams) - 1 else left
            left -= part
            pub_rows.append([pid, tm, k, units, part, "RS-C4C"])

    for (f, r), k in sorted(pub_k.items(), key=lambda kv: f"{kv[0][0]}@{kv[0][1]}".upper()):
        u = draft["fams"][f]["node_units"]
        cv = faulty[(f, r)]["curve"]
        sv = int(cv[min(k, len(cv) - 1)].to_integral_value(ROUND_HALF_EVEN))
        tms = sorted({projs[a]["team"] for a in pool_projects[(f, r)]} | set(rng.sample(_GTEAMS, 2)))
        team_lines(f"{f}@{r}".upper(), k, k * u, sv, tms)
    for f, r in rng.sample([p for p in pools if p not in pub_pools], 6):
        k = rng.randint(2, 9)
        team_lines(f"{f}@{r}".upper(), k, k * draft["fams"][f]["node_units"], rng.randint(1000, 90000), sorted(rng.sample(_GTEAMS, 4)))
    pub_rows.sort()
    _G_write(S["dir"] / "cache_plan_published.csv", _G_csv_text(["pool_id", "team", "nodes", "cache_units", "saving_cents", "ruleset_used"], pub_rows))


def _G_g_reference_files(S: dict) -> None:
    c, rng, data_dir = S["c"], S["rng"], S["dir"]
    projs, merges = S["projs"], S["merges"]
    # ---------------------------------------------------------------- template catalog (appended to feed_layouts.md)
    tl = ["", "## Appendix T. Query template catalog", "",
          "Every template id a feed or an adjustment can carry, with the workload family it belongs to. The",
          "letters before the dash of a template id are where the template was first registered; templates",
          "are re-homed between families over time, and this table is the only record of the family in force.",
          "`owner_team` and `status` are informational.", "",
          "| template_id | family | owner_team | status |", "|---|---|---|---|"]
    trows = sorted(S["tmpl_fam"].items())
    rng.shuffle(trows)
    for tid, f in trows:
        fw = rng.choice([f, f, f, f.upper(), f.title()])
        tl.append(f"| {tid} | {fw} | {rng.choice(_GTEAMS)} | {'retired' if rng.random() < 0.05 else 'active'} |")
    fl = data_dir / "feed_layouts.md"
    base = fl.read_text(encoding="utf-8").split("\n## Appendix T.")[0].rstrip("\n")
    _G_write(fl, base + "\n" + "\n".join(tl) + "\n")

    rc = ["# cluster alias map: every spelling seen in warehouse exports and its canonical cluster", "clusters:"]
    rows_rc = []
    for x, _, _, al in _GCLUSTERS:
        rows_rc.append((x, x))
        for a in al:
            rows_rc.append((a, x))
        for k in range(12):
            rows_rc.append((f"{x.lower().replace('-', '')}-pod-{chr(97 + k)}", x))
    rng.shuffle(rows_rc)
    for a, x in rows_rc:
        q = '"' if " " in a or rng.random() < 0.3 else ""
        rc += [f"  - alias: {q}{a}{q}", f"    canonical: {x}"]
    _G_write(data_dir / "cluster_aliases.yaml", "\n".join(rc) + "\n")

    # ---------------------------------------------------------------- registries and merges
    ids = sorted(projs)
    rng.shuffle(ids)
    main_ids = set(ids[: int(len(ids) * 0.62)])
    archive_ids = [i for i in sorted(projs) if i not in main_ids]
    overlap = rng.sample(sorted(i for i in main_ids if projs[i]["org"] == c["org"] and projs[i]["tier"] == "prod"), 28)
    tier_flip = set(rng.sample(S["devp"], 25)) | set(rng.sample(S["productive"], 25))

    def tier_of(a: str) -> str:
        t = projs[a]["tier"]
        if a in tier_flip:
            t = "prod" if t == "dev" else "dev"
        return t if rng.random() < 0.8 else t.upper()

    main_rows, arch_rows = [], []
    for a in sorted(main_ids):
        p = projs[a]
        main_rows.append([a if rng.random() > 0.05 else a.lower() + " ", p["org"], p["team"], p["status"] if rng.random() > 0.1 else p["status"].lower(),
                          "" if p["closed"] is None else p["closed"].isoformat(), tier_of(a)])
    for a in archive_ids + overlap:
        p = projs[a]
        stale = a in overlap
        org = rng.choice(c["other_orgs"]) if stale and rng.random() < 0.5 else p["org"]
        status = "Closed" if stale and org == p["org"] else p["status"].title()
        closed = p["closed"] if not stale else S["w0l"].date() - timedelta(days=rng.randint(10, 40))
        arch_rows.append([a, org, p["team"] if not stale else rng.choice(_GTEAMS), status,
                          "" if closed is None else closed.strftime("%d/%m/%Y"), tier_of(a).title()])
    rng.shuffle(main_rows)
    rng.shuffle(arch_rows)
    _G_write(data_dir / "proj_registry_main.csv", _G_csv_text(["project_id", "org_id", "team", "project_status", "closed_on", "tier"], main_rows))
    _G_write(data_dir / "proj_registry_archive.tsv", _G_csv_text(["PROJ", "Org", "Team", "Status", "Closed", "Tier"], arch_rows, "\t"))
    mv_rows = []
    for a in sorted(merges):
        t, d = merges[a]
        reason = "merge reversal" if not a.startswith("MG") else rng.choice(["workspace merge", "org restructure", "tenant transfer", "ticket"])
        mv_rows.append([a if rng.random() > 0.06 else a.lower(), t if rng.random() > 0.06 else " " + t, d.isoformat(), reason])
    rng.shuffle(mv_rows)
    _G_write(data_dir / "project_merges.psv", _G_csv_text(["from_project", "merged_into", "merged_on", "reason"], mv_rows, "|"))

    # ---------------------------------------------------------------- journals
    ops = S["ops"]
    jl = [o for o in ops if o["journal"] == "jsonl"]
    jx = [o for o in ops if o["journal"] == "xml"]
    rng.shuffle(jl)
    rng.shuffle(jx)
    keys = ("usage_start_utc", "project", "cluster", "template", "size", "quantity_gib", "option")
    out = []
    for o in jl:
        d = {"seq": o["seq"], "status": o["status"], "op": o["op"], "query_id": o["query_id"] if rng.random() > 0.06 else o["query_id"].lower()}
        for k in keys:
            if k in o:
                d[k] = o[k]
        d["raised_by"] = rng.choice(["platform-ops", "finops-desk", "tenant-request"])
        out.append(json.dumps(d))
    _G_write(data_dir / "scan_adjustments.jsonl", "\n".join(out) + "\n")
    xs = ['<?xml version="1.0" encoding="UTF-8"?>', '<adjustments desk="late">']
    for o in jx:
        inner = f"<op>{o['op']}</op><query>{_G_xesc(o['query_id'])}</query>"
        for k in keys:
            if k in o:
                inner += f"<{k}>{_G_xesc(str(o[k]))}</{k}>"
        xs.append(f'  <entry seq="{o["seq"]}" status="{o["status"]}">{inner}</entry>')
    xs.append("</adjustments>")
    _G_write(data_dir / "scan_adjustments_late.xml", "\n".join(xs) + "\n")

    iv = ['<?xml version="1.0" encoding="UTF-8"?>', '<reservations exported="2026-09-29T06:00:00Z">']
    for x in S["inventory"]:
        st = x["state"] if rng.random() > 0.15 else x["state"].lower()
        iv.append(f'  <reservation id="{x["id"]}" family="{x["f"] if rng.random() > 0.08 else x["f"].upper()}" cluster="{_G_xesc(S["ctok"](x["r"]))}" '
                  f'owner="{_G_xesc(S["ptok"](x["owner"]))}" units="{x["units"]}" start_utc="{_G_iso_z(x["start"])}" end_utc="{_G_iso_z(x["end"])}" state="{st}"/>')
    iv.append("</reservations>")
    _G_write(data_dir / "cache_reservations.xml", "\n".join(iv) + "\n")


def _G_g_decoys(S: dict) -> None:
    c, rng, data_dir = S["c"], S["rng"], S["dir"]
    fam_codes = [f for f, *_ in _GFAMILIES]
    cluster_codes = [x for x, _, _, _ in _GCLUSTERS]
    W0_LOCAL = S["w0l"]
    q4 = Decimal("0.0001")
    dg = ["DRAFT - scan rates digest (prepared before the quarter, not adopted)", "",
          "Flat rates by family, all clusters, cents per normalized unit:", ""]
    for f, base, ratio, _, _ in _GFAMILIES:
        dg.append(f"  {f:<6} scan {base}  node {(Decimal(base) * Decimal(ratio)).quantize(q4)}")
    dg += ["", "Engine factors follow engine_factor_hint.json.", "Growth is applied after existing reservations are netted off.",
           "Volume tier discounts apply only to the cache units above the tier threshold.",
           "Tier discounted node rates are carried at full precision.",
           "Errata are pending review and are not applied to this quarter.",
           "Comments to the pricing committee before the plan freeze.", ""]
    for x in cluster_codes:
        for f in fam_codes:
            dg.append(f"  cluster note {x} {f}: use flat rate")
    _G_write(data_dir / "scan_rates_digest_draft.txt", "\n".join(dg) + "\n")

    draft = S["rulesets"]["DRAFT_RS-C4C"]
    ann = [f"Q4 result-cache capacity announcement (plan {c['plan_id']})", "",
           f"Approved cache nodes for plan {c['plan_id']}: {S['ann_cap']}",
           "Memory budget: not enforced this quarter; size nodes on scan savings alone.",
           "Ruleset: the most recent adoption in the capacity workbook applies.", "Family limits (provisional):"]
    for f in fam_codes:
        ann.append(f"  {f}: {draft['fams'][f]['family_cap']} nodes, minimum purchase {draft['fams'][f]['min_nodes']} nodes")
    ann += ["", "Cluster minimum commitments (provisional, applied to every cluster at once):"]
    for x in sorted(S["m0"]):
        ann.append(f"  {x}: at least {S['m0'][x] + rng.randint(1, 3)} nodes")
    ann += ["", "Project merges are applied from the start of the lookback whatever their merge date.",
            "Figures are provisional and subject to the capacity workbook and the pricing bulletin.", ""]
    for d in range(200):
        ann.append(f"  approval log {d + 1:03d}: request {rng.randint(10000, 99999)} reviewed")
    _G_write(data_dir / "capacity_announce_oct.txt", "\n".join(ann) + "\n")

    cal = ["# platform planning calendar (circulated before the quarter)", f"plan: {c['plan_id']}", "ruleset: RS-C4C",
           f'lookback_start_utc: "{W0_LOCAL:%Y-%m-%d}T00:00:00Z"', f'lookback_end_utc: "{S["w1l"]:%Y-%m-%d}T00:00:00Z"', "events:"]
    for d in range(70):
        day = (W0_LOCAL + timedelta(days=d - 14)).date()
        for reg in rng.sample(cluster_codes, 3):
            cal += [f"  - date: {day.isoformat()}", f"    cluster: {reg}", f"    kind: {rng.choice(['patch window', 'capacity review', 'price watch', 'freeze'])}"]
    _G_write(data_dir / "platform_calendar.yaml", "\n".join(cal) + "\n")

    hint = {"generated": "2026-02-11", "note": "client-side engine factor cache",
            "size_factors": {s: (v if v is not None else "64") for s, v in _GSIZES},
            "engines": [{"engine": f"{f}.{s}", "factor": (v if v is not None else "64") if s != "xs" else "0.5"} for f in fam_codes for s, v in _GSIZES]}
    _G_write(data_dir / "engine_factor_hint.json", json.dumps(hint, indent=1) + "\n")

    dash = []
    for (f, r) in sorted(S["rulesets"][S["inforce"]]["series"]):
        for d in range(14):
            dash.append([f"{f}@{r}".upper(), (W0_LOCAL + timedelta(days=d)).date().isoformat(), f"{rng.uniform(40, 95):.2f}", f"{rng.uniform(55, 99):.2f}"])
    _G_write(data_dir / "hit_ratio_dashboard.csv", _G_csv_text(["pool_id", "day_utc", "hit_ratio_pct", "node_utilization_pct"], dash))

    symptoms = ["plan bought nodes in a cluster we do not plan", "dev project scans counted", "MiB read as GiB",
                "cache hits missing from the baseline", "window starts at midnight UTC", "growth applied after netting",
                "family cap exceeded", "rates look like last quarter", "max engines undercounted", "merged project still on old org",
                "late adjustments ignored", "memory budget blown", "template counted under the wrong family",
                "merge charged before it happened", "cluster below its commitment still planned", "ruleset not yet adopted was used"]
    tickets = []
    for k in range(240):
        tickets.append(json.dumps({"ticket": f"PLT{k + 7100:05d}", "project": rng.choice(S["productive"]), "opened": (S["w1l"] + timedelta(days=rng.randint(0, 2))).date().isoformat(),
                                   "symptom": rng.choice(symptoms), "channel": rng.choice(["portal", "email", "chat"])}))
    _G_write(data_dir / "ops_tickets.ndjson", "\n".join(tickets) + "\n")


def _G_g_workbook(S: dict) -> None:
    c = S["c"]
    wrng = random.Random(S["seed"] + 11)

    def rs_rows(rs: dict, name: str) -> list[list[object]]:
        rows: list[list[object]] = [["section", "key", "value", "note"],
                                    ["PLAN", "node_cap_total", f" {rs['cap']} " if wrng.random() < 0.5 else rs["cap"], "approved cache nodes across all pools"],
                                    ["PLAN", "mem_budget_units", f" {rs['mem']}" if wrng.random() < 0.5 else rs["mem"], "approved memory units across all nodes"],
                                    ["PLAN", "saving_rounding", "half_even", "per pool, to whole cents"],
                                    [],
                                    ["section", "family", "eligible", "node_units", "min_nodes", "family_cap", "growth_pct", "tier_units", "tier_discount_pct", "mem_units_per_node"]]
        fl_ = list(rs["fams"].items())
        wrng.shuffle(fl_)
        for f, v in fl_:
            el = wrng.choice(["Y", "yes", "TRUE", "1"]) if v["eligible"] else wrng.choice(["N", "no", "FALSE", "0"])
            rows.append(["FAM", f, el, v["node_units"], f" {v['min_nodes']}" if wrng.random() < 0.4 else v["min_nodes"],
                         v["family_cap"], f"{v['growth_pct']}" if wrng.random() < 0.5 else v["growth_pct"],
                         v["tier_units"], f" {v['tier_discount_pct']}" if wrng.random() < 0.3 else v["tier_discount_pct"],
                         f"{v['mem_units']} " if wrng.random() < 0.3 else v["mem_units"]])
        rows.append([])
        rows.append(["sheet", name])
        return rows

    def serial(d: date) -> int:
        return (d - date(1904, 1, 1)).days

    start = S["w0l"].date()
    ad = [["adoption_id", "track", "sheet", "effective", "status", "note"]]
    rows = [(aid, "RS-C4", sheet, start + timedelta(days=off), status) for aid, sheet, status, off in c["adoptions"]]
    rows.append(("A-090", "RS-C3", "RS-C4B", start - timedelta(days=2), "ADOPTED"))
    wrng.shuffle(rows)
    for aid, track, sheet, d, status in rows:
        sv = serial(d)
        ad.append([aid, track, sheet, f" {sv}" if wrng.random() < 0.35 else sv, status,
                   {"ADOPTED": "committee minute", "WITHDRAWN": "withdrawn before use", "PROPOSED": "never adopted"}[status]])
    cl_rows: list[list[object]] = [["cluster", "utc_offset", "note"]] + [[x, o, "fixed, no daylight saving"] for x, o, _, _ in _GCLUSTERS]
    readme = [["Capacity workbook FY26"], ["Sheets are named by ruleset version; the Adoptions sheet records which version is in force from which date."],
              ["DRAFT sheets were never adopted."], ["ScanFactors gives the normalized factor of every engine (family.size)."],
              ["Clusters lists the fixed UTC offset of every warehouse cluster."],
              ["mem_budget_units bounds the memory units of all planned nodes together."]]
    R = S["rulesets"]
    sheets = [("README", readme, False), ("RS-C4B", rs_rows(R["RS-C4B"], "RS-C4B"), False),
              ("DRAFT_RS-C4C", rs_rows(R["DRAFT_RS-C4C"], "DRAFT_RS-C4C"), True), ("ScanFactors", S["size_rows"], False),
              ("RS-C4A", rs_rows(R["RS-C4A"], "RS-C4A"), False), ("Clusters", cl_rows, False), ("Adoptions", ad, False),
              ("RS-C4D", rs_rows(R["RS-C4D"], "RS-C4D"), False)]
    order = list(range(1, len(sheets) + 1))
    wrng.shuffle(order)
    _G_xlsx(S["dir"] / "capacity_workbook_fy26.xlsx", sheets, order, wrng)


def _G_g_bulletin(S: dict) -> None:
    c = S["c"]
    prng = random.Random(S["seed"] + 17)
    fam_codes = [f for f, *_ in _GFAMILIES]
    cluster_codes = [x for x, _, _, _ in _GCLUSTERS]
    errata = [list(e) for e in S["errata"]]
    m1 = dict(S["m1"])
    if c["policy_salt"]:
        prg = random.Random(S["seed"] * 31 + c["policy_salt"])
        count: dict[tuple, int] = {}
        for e in errata:
            count[(e[1], e[2], e[3])] = count.get((e[1], e[2], e[3]), 0) + 1
        single = [k for k, e in enumerate(errata) if count[(e[1], e[2], e[3])] == 1]
        for k in prg.sample(single, min(10, len(single))):
            errata[k][5] = "RESCINDED" if errata[k][5] == "IN FORCE" else "IN FORCE"
        for r in sorted(m1):
            m1[r] = max(2, int(m1[r] * prg.uniform(0.7, 1.6)))
    intro = [["Platform Pricing Committee"], [f"Result-Cache Pricing Bulletin Q4-26 (adopted for plan {c['plan_id']})"],
             ["Applies to cache capacity planning for the plan named above and later plans."],
             ["This bulletin withdraws Table R-1 of the Q3 bulletin and the scan rates digest draft."],
             ["Table R-2 gives, per family and cluster, the scan rate and the cache node rate."],
             ["Both rates are in cents per normalized unit (scan) and per normalized unit-hour (node), four decimals."],
             ["Table E-1 lists errata to Table R-2, applied in ascending erratum_id order; IN FORCE replaces the named rate."],
             ["A RESCINDED erratum has no effect."],
             ["Table C-1 records committee rulings on existing reservations by reservation id."],
             ["A CANCELLED reservation no longer exists for planning."],
             ["An EXTENDED reservation ends at the revised UTC time shown instead of its inventory end."],
             ["Table M-1 gives the minimum node commitment of each cluster. Table M-0 is superseded by Table M-1."]]
    hdr = ["family", "cluster", "scan_rate_cents", "node_rate_cents"]
    r1, r2 = S["r1"], S["r2"]
    rowsr1 = [[f, x, str(r1[(f, x)][0]), str(r1[(f, x)][1])] for f in fam_codes for x in cluster_codes]
    rowsr2 = [[f, x, str(r2[(f, x)][0]), str(r2[(f, x)][1])] for f in sorted(fam_codes) for x in sorted(cluster_codes)]
    ehdr = ["erratum_id", "family", "cluster", "field", "new_value", "status"]
    erows = []
    for eid, f, x, fld, new, status in errata:
        erows.append([eid, f if prng.random() > 0.3 else f.upper(), x if prng.random() > 0.3 else x.lower(), fld, str(new), status])
    prng.shuffle(erows)
    mhdr = ["cluster", "min_nodes"]
    m0rows = [[x if prng.random() > 0.3 else x.lower(), str(v)] for x, v in sorted(S["m0"].items())]
    m1rows = [[x if prng.random() > 0.3 else x.lower(), str(v)] for x, v in sorted(m1.items())]
    prng.shuffle(m1rows)
    w1 = [["Table R-1 (Q3 bulletin, WITHDRAWN)"], hdr] + rowsr1
    w2 = [["Table R-2 (in force)"], hdr] + rowsr2
    e1 = [["Table E-1 errata to Table R-2"], ehdr] + erows
    c1 = [["Table C-1 reservation rulings"], ["reservation_id", "ruling", "revised_end_utc"]] + [list(x) for x in S["inv_rulings"]]
    mm = [["Table M-0 cluster commitments (SUPERSEDED)"], mhdr] + m0rows + [["Table M-1 cluster commitments (in force)"], mhdr] + m1rows
    pages = _G_paginate(intro + w1, 70, 66, hdr, "Table R-1 (continued)")
    pages += _G_paginate(w2, 70, 66, hdr, "Table R-2 (continued)")
    pages += _G_paginate(e1, 70, 66, ehdr, "Table E-1 (continued)")
    pages += _G_paginate(c1, 70, 66, ["reservation_id", "ruling", "revised_end_utc"], "Table C-1 (continued)")
    pages += [mm + [["End of Bulletin Q4-26"]]]
    _G_pdf(S["dir"] / "pricing_bulletin_q4.pdf", pages, prng)


def _G_g_profile(S: dict) -> None:
    c = S["c"]
    frng = random.Random(S["seed"] + 29)
    alias_of = {x: al for x, _, _, al in _GCLUSTERS}
    merges = S["merges"]
    far = S["w1"] + timedelta(days=30)
    aliases_for: dict[str, list[str]] = {}
    for a in sorted(merges):
        aliases_for.setdefault(S["resolve"](a, far), []).append(a)

    def ctok(code: str) -> str:
        r = frng.random()
        if r < 0.55:
            return code
        if r < 0.62:
            return code.lower()
        return frng.choice(alias_of[code])

    def ptok(p: str) -> str:
        al = aliases_for.get(p)
        return frng.choice(al) if al and frng.random() < 0.3 else p

    in_scope = list(c["in_scope"])
    outages = list(S["outages"])
    devl = list(S["devp"])
    if c["profile_salt"]:
        q = random.Random(S["seed"] * 37 + c["profile_salt"])
        devl += q.sample(sorted({a for ps in S["pool_projects"].values() for a in ps}), 6)
        for _ in range(4):
            r = q.choice(in_scope)
            a0 = S["w0l"] + _GHOUR * q.randint(0, S["nh"] - 12)
            outages.append((r, a0, a0 + _GHOUR * q.randint(3, 10)))
        in_scope.remove(q.choice(in_scope))
    prof = ["# result-cache capacity planning profile exported by the platform team", f'plan_id: "{c["plan_id"]}"', f'org_id: "{c["org"]}"',
            f'billing_offset: "{c["billing"]}"', f'lookback_start_local: "{S["w0l"]:%Y-%m-%dT%H:%M:%S}"',
            f'lookback_end_local: "{S["w1l"]:%Y-%m-%dT%H:%M:%S}"', f'horizon_end_utc: "{_G_iso_z(S["horizon"])}"',
            "ruleset_track: RS-C4", "published_plan: cache_plan_published.csv", "clusters_in_scope:"]
    for r in in_scope:
        prof.append(f"  - cluster: {ctok(r).strip() if frng.random() < 0.4 else r}")
    prof.append("outage_windows:")
    for r, a0, a1 in outages:
        prof += [f"  - cluster: \"{ctok(r).strip()}\"", f"    from_local: \"{a0:%Y-%m-%dT%H:%M:%S}\"", f"    to_local: \"{a1:%Y-%m-%dT%H:%M:%S}\""]
    prof.append("dev_projects:")
    frng.shuffle(devl)
    for a in devl:
        prof.append(f"  - project: {ptok(a).strip()}")
    _G_write(S["dir"] / "plan_profile_qa4.yml", "\n".join(prof) + "\n")


# =========================================================================== reference
_MEMO: dict[str, Any] = {}
# rewardkit runs criteria in parallel threads; every memoised computation runs under this lock so a
# result is computed once and no thread reads a half-built entry.
_LOCK = threading.RLock()
Z = timezone.utc
H1 = timedelta(hours=1)
XNS = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
D0 = Decimal(0)


# =========================================================================== parsing
def _k(v: Any) -> str:
    s = str(v).strip()
    while len(s) > 1 and s[0] == s[-1] and s[0] in "'\"":
        s = s[1:-1].strip()
    return s.upper()


def _uq(v: str) -> str:
    v = v.strip()
    return v[1:-1] if len(v) > 1 and v[0] == v[-1] and v[0] in "'\"" else v


def _off(text: str) -> timezone:
    t = text.strip()
    sign = -1 if t[0] == "-" else 1
    hh, mm = t.lstrip("+-").split(":")
    return timezone(sign * timedelta(hours=int(hh), minutes=int(mm)))


def _iso(t: datetime) -> str:
    return t.astimezone(Z).strftime("%Y-%m-%dT%H:%M:%SZ")


def _utc(text: str) -> datetime:
    return datetime.fromisoformat(_uq(text).replace("Z", "+00:00")).astimezone(Z)


def _p(d: Decimal) -> str:
    if d == 0:
        return "0"
    s = format(d.normalize(), "f")
    return s.rstrip("0").rstrip(".") if "." in s else s


def _he(d: Decimal) -> int:
    return int(d.to_integral_value(ROUND_HALF_EVEN))


def _pc(a: Decimal, b: Decimal) -> str:
    return str((a * 100 / b).quantize(Decimal("0.01"), ROUND_HALF_EVEN))


def _rows(text: str, sep: str) -> list[dict[str, str]]:
    return list(csv.DictReader(io.StringIO(text.lstrip("\ufeff")), delimiter=sep))


def _yaml(text: str) -> tuple[dict[str, str], dict[str, list[dict[str, str]]]]:
    scal: dict[str, str] = {}
    seqs: dict[str, list[dict[str, str]]] = {}
    sect = ""
    item: dict[str, str] | None = None
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith("#"):
            continue
        if not raw.startswith((" ", "-")):
            key, _, val = raw.partition(":")
            if val.strip():
                scal[key.strip()] = _uq(val)
                sect = "?"
            else:
                sect = key.strip()
                seqs.setdefault(sect, [])
            item = None
            continue
        body = raw.strip()
        if body.startswith("- "):
            key, _, val = body[2:].partition(":")
            item = {key.strip(): _uq(val)}
            seqs.setdefault(sect, []).append(item)
        elif item is not None and ":" in body:
            key, _, val = body.partition(":")
            item[key.strip()] = _uq(val)
    return scal, seqs


def _sheet(path: Path, name: str) -> list[dict[str, str]]:
    rel = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"
    with zipfile.ZipFile(path) as z:
        wb = ET.fromstring(z.read("xl/workbook.xml"))
        rels = {r.attrib["Id"]: r.attrib["Target"] for r in ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))}
        rid = next(s.attrib[rel] for s in wb.iter(XNS + "sheet") if s.attrib["name"] == name)
        sst = ["".join(t.text or "" for t in si.iter(XNS + "t")) for si in ET.fromstring(z.read("xl/sharedStrings.xml")).iter(XNS + "si")]
        ws = ET.fromstring(z.read("xl/" + rels[rid].lstrip("/").removeprefix("xl/")))
    grid = []
    for row in ws.iter(XNS + "row"):
        cells = {}
        for c in row.iter(XNS + "c"):
            col = re.match(r"[A-Z]+", c.attrib["r"]).group(0)
            if c.attrib.get("t") == "inlineStr":
                cells[col] = "".join(t.text or "" for t in c.iter(XNS + "t"))
                continue
            v = c.find(XNS + "v")
            if v is not None:
                cells[col] = sst[int(v.text)] if c.attrib.get("t") == "s" else v.text
        grid.append(cells)
    return grid


_STR = re.compile(r"\((?:\\.|[^\\)])*\)|<[0-9A-Fa-f\s]*>")


_TOK = re.compile(r"\((?:\\.|[^\\)])*\)|<[0-9A-Fa-f\s]*>|[\[\]]|[^\s()<>\[\]]+")
_NUM = re.compile(r"[-+]?[\d.]+")


def _lit(s: str) -> str:
    if s.startswith("<"):
        return bytes.fromhex("".join(s[1:-1].split())).decode("latin-1")
    return re.sub(r"\\(.)", r"\1", s[1:-1])


def _pdf(path: Path) -> list[list[str]]:
    raw = path.read_bytes()
    obj = {int(m.group(1)): m.group(2) for m in re.finditer(rb"(?s)(\d+) 0 obj\n(.*?)\nendobj", raw)}
    root = next(v for v in obj.values() if b"/Type /Pages " in v)
    out: list[list[str]] = []
    for kid in re.findall(rb"(\d+) 0 R", root.split(b"/Kids [", 1)[1].split(b"]", 1)[0]):
        cid = int(re.search(rb"/Contents (\d+) 0 R", obj[int(kid)]).group(1))
        m = re.match(rb"(?s)<< /Length (\d+) /Filter /FlateDecode >>\nstream\n", obj[cid])
        text = zlib.decompress(obj[cid][m.end():m.end() + int(m.group(1))]).decode("latin-1")
        grid: dict[Decimal, list[tuple[Decimal, str]]] = {}
        nums: list[str] = []
        strs: list[str] = []
        x = y = D0
        for tok in _TOK.findall(text):
            if tok[0] in "(<":
                strs.append(_lit(tok))
            elif tok in "[]":
                pass
            elif _NUM.fullmatch(tok):
                nums.append(tok)
            elif tok == "Tm":
                x, y = Decimal(nums[-2]), Decimal(nums[-1])
                nums, strs = [], []
            elif tok in ("Tj", "TJ"):
                grid.setdefault(y, []).append((x, "".join(strs)))
                nums, strs = [], []
            else:
                nums, strs = [], []
        for y in sorted(grid, reverse=True):
            out.append([c for _, c in sorted(grid[y])])
    return out


_FIELDS = {
    "jsonl_flat": ("qid", "start", "proj", "clu", "tpl", "wh", "gib", "opt", "st", "rev"),
    "csv_a": ("query_id", "started_utc", "project_id", "cluster", "template_id", "wh_size", "scanned_gib", "cache_option", "query_status", "revision"),
    "tsv_epoch": ("id", "epoch_s", "proj", "clu", "tpl", "wh", "scan_kib", "opt", "st", "rev"),
    "psv_local": ("id", "local_start", "proj", "clu", "tpl", "wh", "gib", "opt", "st", "rev"),
    "xml_attr": ("id", "t", "p", "c", "tp", "w", "g", "o", "s", "v"),
    "yaml_list": ("id", "start", "project", "cluster", "template", "size", "gib", "option", "status", "rev"),
    "json_array": ("queryId", "epochMillis", "projectId", "clusterCode", "templateId", "whSize", "scannedMib", "option", "status", "revision"),
    "csv_offset": ("query", "ts_offset", "project", "cluster", "template", "size", "kib", "opt", "code", "rev"),
    "xml_elem": ("id", "epoch", "project", "cluster", "template", "size", "gib", "option", "status", "rev"),
    "txt_kv": ("query", "at", "project", "cluster", "template", "size", "gib", "option", "state", "rev"),
}
_SEP = {"csv_a": ",", "tsv_epoch": "\t", "psv_local": "|", "csv_offset": ","}


def _feed(path: Path, layout: str) -> list[tuple[str, ...]]:
    out: list[tuple] = []
    if layout == "sqlite_rows":
        con = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
        out = list(con.execute("SELECT query_id, started_utc, project_id, cluster, template_id, wh_size, scanned_gib, cache_option, query_status, revision FROM query_log"))
        con.close()
    elif layout == "db_rows":
        con = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
        out = list(con.execute("SELECT qid, ep, prj, clu, tpl, wh, cg, oc, sc, rv FROM ql"))
        con.close()
    else:
        text = path.read_text(encoding="utf-8")
        if layout in _SEP:
            out = [tuple(r[f] for f in _FIELDS[layout]) for r in _rows(text, _SEP[layout])]
        elif layout == "jsonl_flat":
            out = [tuple(o[f] for f in _FIELDS[layout]) for o in map(json.loads, filter(str.strip, text.splitlines()))]
        elif layout == "ndjson_nested":
            for o in map(json.loads, filter(str.strip, text.splitlines())):
                c = o["ctx"]
                out.append((o["query"]["id"], o["scan"]["start"], c["project"], c["cluster"], c["template"], c["size"],
                            o["scan"]["mib"], o["bill"]["option"], o["bill"]["status"], o["query"]["rev"]))
        elif layout == "txt_fixed":
            cuts = [(0, 12), (12, 26), (26, 38), (38, 63), (63, 73), (73, 77), (77, 89), (89, 91), (91, 92), (92, 95)]
            out = [tuple(ln[a:b] for a, b in cuts) for ln in text.splitlines() if ln.strip() and not ln.startswith("#")]
        elif layout in ("xml_attr", "xml_elem"):
            tag = "q" if layout == "xml_attr" else "query"
            for e in ET.fromstring(text).iter(tag):
                g = e.attrib if layout == "xml_attr" else {c.tag: c.text or "" for c in e}
                out.append(tuple(g[f] for f in _FIELDS[layout]))
        elif layout == "yaml_list":
            out = [tuple(i[f] for f in _FIELDS[layout]) for i in _yaml(text)[1].get("records", [])]
        elif layout == "json_array":
            out = [tuple(o[f] for f in _FIELDS[layout]) for o in json.loads(text)["export"]["rows"]]
        elif layout == "yml_list":
            for i in _yaml(text)[1].get("", []):
                size, tpl = i["shape"].split("@", 1)
                out.append((i["qid"], i["local"], i["prj"], i["clu"], tpl, size, i["gib"], i["o"], i["s"], i["rev"]))
        elif layout == "json_keyed":
            out = [(k, o["ms"], o["p"], o["c"], o["t"], o["w"], o["mib"], o["o"], o["s"], o["v"]) for k, o in json.loads(text).items()]
        elif layout == "txt_kv":
            for ln in text.splitlines():
                if ln.strip() and not ln.startswith("#"):
                    kv = {m.group(1): _uq(m.group(2)) for m in re.finditer(r'(\w+)=("[^"]*"|\S+)', ln)}
                    out.append(tuple(kv[f] for f in _FIELDS["txt_kv"]))
        else:
            raise ValueError(layout)
    return [tuple(str(x) for x in r) for r in out]


_UNIT = {"gib": 1, "mib": 1024, "kib": 1048576, "cgib": 100}


# =========================================================================== reference
def _state(root: Path, flip: str = "") -> dict[str, Any]:
    st: dict[str, Any] = {"flip": flip}
    scal, seqs = _yaml((root / "plan_profile_qa4.yml").read_text(encoding="utf-8"))
    st["scal"] = scal
    bill = _off(scal["billing_offset"])
    w0l = datetime.fromisoformat(scal["lookback_start_local"])
    w0 = w0l.replace(tzinfo=bill).astimezone(Z)
    w1 = datetime.fromisoformat(scal["lookback_end_local"]).replace(tzinfo=bill).astimezone(Z)
    nh = (w1 - w0) // H1
    horizon = _utc(scal["horizon_end_utc"])
    org = _k(scal["org_id"])
    st.update(w0=w0, nh=nh, w1=w1)

    rmap = {_k(i["alias"]): _k(i["canonical"]) for i in _yaml((root / "cluster_aliases.yaml").read_text(encoding="utf-8"))[1]["clusters"]}
    reg_of = lambda tok: rmap.get(_k(tok), _k(tok))  # noqa: E731
    merges = {_k(r["from_project"]): (_k(r["merged_into"]), datetime.fromisoformat(r["merged_on"].strip()).replace(tzinfo=bill).astimezone(Z))
              for r in _rows((root / "project_merges.psv").read_text(encoding="utf-8"), "|")}

    def proj(tok: str, at: datetime) -> tuple[str, int]:
        x, path = _k(tok), []
        while x in merges and (merges[x][1] <= at or flip == "ungated_merges"):
            path.append(x)
            x = merges[x][0]
            if x in path:
                ring = path[path.index(x):]
                return (x if flip == "cycle_last" else min(ring)), len(path)
        return x, len(path)

    st["merges"], st["proj"] = merges, proj
    scope_cl = {reg_of(i["cluster"]) for i in seqs.get("clusters_in_scope", [])}
    dev = {proj(i["project"], w1)[0] for i in seqs.get("dev_projects", [])}
    bad_hours: dict[str, set[int]] = {}
    for i in seqs.get("outage_windows", []):
        a = datetime.fromisoformat(i["from_local"]).replace(tzinfo=bill).astimezone(Z)
        b = datetime.fromisoformat(i["to_local"]).replace(tzinfo=bill).astimezone(Z)
        s = bad_hours.setdefault(reg_of(i["cluster"]), set())
        for h in range(nh):
            if a <= w0 + H1 * h < b:
                s.add(h)

    # template catalog (Appendix T of feed_layouts.md)
    tcat: dict[str, str] = {}
    on = False
    for ln in (root / "feed_layouts.md").read_text(encoding="utf-8").splitlines():
        if ln.startswith("## "):
            on = "Appendix T" in ln
            continue
        if on and ln.startswith("|"):
            cells = [c.strip() for c in ln.strip().strip("|").split("|")]
            if cells[0] in ("template_id", "---") or set(cells[0]) <= {"-"}:
                continue
            tcat[_k(cells[0])] = cells[1].lower()
    st["tcat"] = tcat

    book = root / "capacity_workbook_fy26.xlsx"
    with zipfile.ZipFile(book) as z:
        m1904 = re.search(r'date1904="([^"]*)"', z.read("xl/workbook.xml").decode("utf-8"))
    base = date(1904, 1, 1) if (m1904 and m1904.group(1).lower() in ("1", "true")) else date(1899, 12, 30)
    if flip == "date1900":
        base = date(1899, 12, 30)
    adopt = []
    for c in _sheet(book, "Adoptions"):
        if c.get("A", "").strip() and c.get("A", "").strip() != "adoption_id":
            if _k(c["B"]) == _k(scal["ruleset_track"]) and _k(c["E"]) == "ADOPTED":
                adopt.append((base + timedelta(days=int(c["D"].strip())), c["C"].strip(), _k(c["A"])))
    if flip != "latest_adoption":
        adopt = [a for a in adopt if a[0] <= w0l.date()]
    eff_date, sheet, adoption = max(adopt)
    plan_kv: dict[str, str] = {}
    fams: dict[str, dict] = {}
    for c in _sheet(book, sheet):
        sec = (c.get("A") or "").strip()
        if sec == "PLAN":
            plan_kv[c["B"].strip()] = c["C"].strip()
        elif sec == "FAM":
            n = lambda col: int(Decimal(c[col].strip()))  # noqa: E731
            fams[c["B"].strip().lower()] = {"eligible": c["C"].strip().lower() in {"y", "yes", "true", "1"}, "node_units": n("D"),
                                            "min_nodes": n("E"), "family_cap": n("F"), "growth_pct": n("G"),
                                            "tier_units": n("H"), "tier_discount_pct": n("I"), "mem_units_per_node": n("J")}
    cap = int(Decimal(plan_kv["node_cap_total"]))
    mem = int(Decimal(plan_kv["mem_budget_units"]))
    st.update(sheet=sheet, cap=cap, mem=mem, rounding=plan_kv["saving_rounding"], fams=fams, adoption=adoption, eff_date=eff_date)
    sizef = {c["A"].strip().lower(): Decimal(c["B"].strip()) for c in _sheet(book, "ScanFactors")
             if c.get("A") and c["A"].strip() != "engine"}
    roff = {_k(c["A"]): _off(c["B"]) for c in _sheet(book, "Clusters") if c.get("A") and c["A"].strip() != "cluster"}

    rates: dict[tuple[str, str], list[str]] = {}
    rulings: dict[str, tuple[str, str]] = {}
    errata: list[tuple[str, str, str, str, str]] = []
    eids: list[str] = []
    mins: dict[str, dict[str, int]] = {"M-0": {}, "M-1": {}}
    where = ""
    for cells in _pdf(root / "pricing_bulletin_q4.pdf"):
        if len(cells) == 1:
            hit = re.match(r"Table ([A-Z]-\d)", cells[0])
            where = hit.group(1) if hit else where
            continue
        if where in mins and cells[0] != "cluster":
            mins[where][reg_of(cells[0])] = int(cells[1])
        elif where == "R-2" and cells[0] != "family":
            rates[(cells[0].lower(), reg_of(cells[1]))] = [cells[2], cells[3]]
        elif where == "E-1" and cells[0] != "erratum_id":
            errata.append((cells[1].strip().lower(), reg_of(cells[2]), cells[3].strip(), cells[4].strip(), cells[5].strip().upper()))
            eids.append(cells[0].strip())
        elif where == "C-1" and cells[0] != "reservation_id":
            rulings[_k(cells[0])] = (cells[1].strip().upper(), cells[2].strip())
    order = range(len(errata)) if flip == "errata_unsorted" else sorted(range(len(errata)), key=lambda i: eids[i])
    for fam, cl, fld, val, status in (errata[i] for i in order):
        if status == "IN FORCE" or (flip == "rescinded" and status == "RESCINDED"):
            rates[(fam, cl)][0 if fld == "scan_rate_cents" else 1] = val
    st["errata"] = errata
    st["commit"] = mins["M-0" if flip == "m0_table" else "M-1"]

    registry: dict[str, dict] = {}
    for r in _rows((root / "proj_registry_archive.tsv").read_text(encoding="utf-8"), "\t"):
        cl = r["Closed"].strip()
        registry[_k(r["PROJ"])] = {"org": _k(r["Org"]), "team": _k(r["Team"]), "status": r["Status"].strip().upper(),
                                   "closed": datetime.strptime(cl, "%d/%m/%Y").date() if cl else None}
    for r in _rows((root / "proj_registry_main.csv").read_text(encoding="utf-8"), ","):
        cl = r["closed_on"].strip()
        registry[_k(r["project_id"])] = {"org": _k(r["org_id"]), "team": _k(r["team"]),
                                         "status": r["project_status"].strip().upper(), "closed": date.fromisoformat(cl) if cl else None}
    st["registry"] = registry

    def scope(a: str) -> str:
        r = registry.get(a)
        if r is None:
            return "UNKNOWN_PROJECT"
        if r["org"] != org:
            return "OTHER_ORG"
        if r["status"] == "CLOSED" and r["closed"] is not None and r["closed"] < w0l.date():
            return "CLOSED_PROJECT"
        return "DEV_PROJECT" if a in dev else ""

    st["scope"], st["org"] = scope, org

    def stamp(raw: str, conv: str, ctk: str) -> datetime:
        v = _uq(raw)
        if conv in ("iso_z", "iso_offset"):
            return _utc(v)
        if conv in ("epoch_s", "epoch_ms"):
            n = int(v)
            return datetime(1970, 1, 1, tzinfo=Z) + (timedelta(seconds=n) if conv == "epoch_s" else timedelta(milliseconds=n))
        if conv == "compact_utc":
            return datetime.strptime(v, "%Y%m%d%H%M%S").replace(tzinfo=Z)
        wall = datetime.strptime(v.replace("T", " "), "%Y-%m-%d %H:%M:%S")
        return wall.replace(tzinfo=bill if conv == "local_billing" else roff[reg_of(ctk)]).astimezone(Z)

    man = json.loads((root / "ingest_manifest_r7.json").read_text(encoding="utf-8"))
    winner: dict[str, tuple[int, str, dict]] = {}
    lineage: dict[str, dict] = {}
    read = dropped = 0
    for sh in man["shards"]:
        fn = sh["file"]
        omap = {a.strip(): b for a, b in sh["option_codes"].items()}
        smap = {a.strip(): b for a, b in sh["status_codes"].items()}
        unit = Decimal(_UNIT[sh["qty_unit"]])
        rows = _feed(root / fn, sh["layout"])
        lineage[fn] = {"kept": 0, "rows": len(rows)}
        for qid, ts, pj, cl, tp, sz, q, o, s, rv in rows:
            read += 1
            key, rev = _k(qid), int(rv)
            prev = winner.get(key)
            if prev is not None:
                dropped += 1
                if prev[0] >= rev:
                    continue
            winner[key] = (rev, fn, {"t": stamp(ts, sh["ts_convention"], cl), "proj": pj, "cl": cl, "tpl": _k(tp),
                                     "size": sz.strip().lower(), "gib": Decimal(q.strip()) / unit,
                                     "opt": omap[o.strip()], "st": smap[s.strip()]})
    live: dict[str, dict] = {}
    voided = 0
    for key, (_, fn, rec) in winner.items():
        if rec["st"] == "V":
            voided += 1
        else:
            live[key] = rec
            lineage[fn]["kept"] += 1
    st["dedup"] = {"duplicate_rows_dropped": dropped, "live_queries": len(live), "rows_read": read, "voided_rows": voided}
    st["lineage"] = lineage

    journal = [dict(json.loads(x), journal="jsonl") for x in (root / "scan_adjustments.jsonl").read_text(encoding="utf-8").splitlines() if x.strip()]
    for e in ET.fromstring((root / "scan_adjustments_late.xml").read_text(encoding="utf-8")).iter("entry"):
        g = {c.tag: (c.text or "").strip() for c in e}
        g["query_id"] = g.pop("query")
        journal.append(dict(g, seq=e.attrib["seq"], status=e.attrib["status"], journal="xml"))
    applied = []
    for o in sorted(journal, key=lambda x: int(x["seq"])):
        if str(o["status"]).strip().lower() != "posted":
            continue
        op, key = o["op"].strip().upper(), _k(o["query_id"])
        if op == "ADD":
            res = "skipped_duplicate" if key in live else "applied"
            if res == "applied":
                live[key] = {"t": _utc(o["usage_start_utc"]), "proj": o["project"], "cl": o["cluster"], "tpl": _k(o["template"]),
                             "size": o["size"].strip().lower(), "gib": Decimal(str(o["quantity_gib"]).strip()),
                             "opt": o["option"].strip().upper(), "st": "F"}
        elif key not in live:
            res = "skipped_missing"
        else:
            res = "applied"
            if op == "VOID":
                live.pop(key)
            elif op == "SETQTY":
                live[key]["gib"] = Decimal(str(o["quantity_gib"]).strip())
            elif op == "MOVE":
                live[key]["proj"] = o["project"]
            elif op == "RETAG" and flip != "no_retag":
                live[key]["tpl"] = _k(o["template"])
        applied.append({"journal": o["journal"], "op": op, "outcome": res, "query_id": key, "seq": int(o["seq"])})
    st["applied"] = applied

    elig = lambda f: f in fams and fams[f]["eligible"]  # noqa: E731
    excl, oow = [], 0
    use: dict[str, dict[int, Decimal]] = {}
    puse: dict[str, dict[str, Decimal]] = {}
    where_of: dict[str, tuple[str, str]] = {}
    for key in sorted(live):
        q = live[key]
        if not (w0 <= q["t"] < w1):
            oow += 1
            continue
        a = proj(q["proj"], q["t"])[0]
        cl = reg_of(q["cl"])
        fam = tcat[q["tpl"]]
        h = (q["t"] - w0) // H1
        reason = scope(a) or ("CLUSTER_OUT_OF_SCOPE" if cl not in scope_cl else "") or \
            ("INELIGIBLE_FAMILY" if not elig(fam) else "") or ("BATCH_QUERY" if q["opt"] == "B" else "") or \
            ("OUTAGE_HOUR" if h in bad_hours.get(cl, set()) else "")
        if reason:
            excl.append({"query_id": key, "reason": reason})
            continue
        pid = fam.upper() + "@" + cl
        where_of[pid] = (fam, cl)
        u = q["gib"] * sizef[fam + "." + q["size"]]
        if flip != "no_stage_rounding":
            u = u.quantize(Decimal("0.001"), ROUND_HALF_EVEN)
        use.setdefault(pid, {})[h] = use.get(pid, {}).get(h, D0) + u
        puse.setdefault(pid, {})[a] = puse.get(pid, {}).get(a, D0) + u
    st.update(excl=excl, oow=oow, use=use, puse=puse)

    netted: dict[str, Decimal] = {}
    inv = []
    for e in ET.fromstring((root / "cache_reservations.xml").read_text(encoding="utf-8")).iter("reservation"):
        rid, fam, cl = _k(e.attrib["id"]), e.attrib["family"].strip().lower(), reg_of(e.attrib["cluster"])
        owner = proj(e.attrib["owner"], w1)[0]
        units = Decimal(e.attrib["units"].strip())
        rul, rev = rulings.get(rid, ("", ""))
        end = _utc(rev) if rul == "EXTENDED" else _utc(e.attrib["end_utc"])
        pid = fam.upper() + "@" + cl
        if rul == "CANCELLED":
            s = "CANCELLED"
        elif e.attrib["state"].strip().upper() != "ACTIVE":
            s = "NOT_ACTIVE"
        elif scope(owner):
            s = "OWNER_OUT_OF_SCOPE"
        elif cl not in scope_cl or not elig(fam):
            s = "NO_POOL"
        elif end < horizon:
            s = "LAPSES"
        else:
            s = "NETTED"
            netted[pid] = netted.get(pid, D0) + units
        inv.append([rid, pid, owner, _p(units), _iso(end), s])
    st["inv"] = sorted(inv)
    st["netted"] = netted

    pools: dict[str, dict] = {}
    xpools = []
    for pid in sorted(use):
        fam, cl = where_of[pid]
        cfg = fams[fam]
        valid = [h for h in range(nh) if h not in bad_hours.get(cl, set())]
        e = netted.get(pid, D0)
        mult = Decimal(100 + cfg["growth_pct"]) / Decimal(100)
        def grown(v: Decimal) -> Decimal:
            return v if flip == "no_stage_rounding" else v.quantize(Decimal("0.01"), ROUND_HALF_EVEN)
        load = {h: max(D0, grown(use[pid].get(h, D0) * mult) - e) for h in valid}
        sc, nd = (Decimal(x) for x in rates[(fam, cl)])
        b, m = cfg["node_units"], cfg["min_nodes"]
        peak = max(load.values(), default=D0)
        kmax = int((peak / b).to_integral_value(ROUND_FLOOR))
        tier, tp = cfg["tier_units"], cfg["tier_discount_pct"]
        P = {"fam": fam, "cl": cl, "valid": valid, "load": load, "sc": sc, "nd": nd, "b": b, "m": m, "e": e,
             "g": cfg["growth_pct"], "rates": rates[(fam, cl)], "tier": tier, "tp": tp, "mu": cfg["mem_units_per_node"],
             "eff": lambda c, nd=nd, tier=tier, tp=tp: nd if c < tier else (
                 nd * (100 - tp) / 100 if flip == "unrounded_discount" else (nd * (100 - tp) / 100).quantize(Decimal("0.0001"), ROUND_HALF_EVEN))}
        pools[pid] = P
        if peak == 0 or kmax < m:
            xpools.append({"pool_id": pid, "reason": "NO_RESIDUAL" if peak == 0 else "BELOW_MIN_NODES"})
            continue
        xs = sorted(load.values())
        pre = [D0]
        for x in xs:
            pre.append(pre[-1] + x)
        P["curve"] = {}
        for k in [0] + list(range(m, kmax + 1)):
            c = Decimal(b * k)
            i = bisect.bisect_left(xs, c)
            cov = pre[i] + c * (len(xs) - i)
            P["curve"][k] = (cov, sc * cov - P["eff"](c) * len(valid) * c)
    cands = [p for p in sorted(pools) if "curve" in pools[p]]
    st.update(pools=pools, xpools=xpools, cands=cands)

    def optimum(shut: set[str]) -> tuple[dict[str, int], Decimal]:
        # family tables for exactly t nodes, then families under the node cap and the memory budget
        famlist = sorted({pools[p]["fam"] for p in cands}, key=lambda f: f.upper())
        table: dict[str, list[tuple[Decimal, tuple] | None]] = {}
        for fam in famlist:
            fc = fams[fam]["family_cap"]
            best: list[tuple[Decimal, tuple] | None] = [None] * (fc + 1)
            best[0] = (D0, ())
            for p in (q for q in cands if pools[q]["fam"] == fam):
                nxt: list[tuple[Decimal, tuple] | None] = [None] * (fc + 1)
                for t in range(fc + 1):
                    if best[t] is None:
                        continue
                    v, vec = best[t]
                    for k, (_, s) in pools[p]["curve"].items():
                        if t + k > fc:
                            break
                        if k and pools[p]["cl"] in shut:
                            continue
                        cur = nxt[t + k]
                        cand = (v + s, vec + (k,))
                        if cur is None or cand[0] > cur[0] or (cand[0] == cur[0] and cand[1] < cur[1]):
                            nxt[t + k] = cand
                best = nxt
            table[fam] = best
        layer: dict[tuple[int, int], tuple[Decimal, tuple]] = {(0, 0): (D0, ())}
        for fam in famlist:
            mu = fams[fam]["mem_units_per_node"]
            nxt2: dict[tuple[int, int], tuple[Decimal, tuple]] = {}
            for (t, mm), (v, tots) in layer.items():
                for ft, cell in enumerate(table[fam]):
                    if t + ft > cap or mm + ft * mu > mem:
                        break
                    if cell is None:
                        continue
                    key2 = (t + ft, mm + ft * mu)
                    cand = (v + cell[0], tots + (ft,))
                    cur = nxt2.get(key2)
                    if cur is None or cand[0] > cur[0] or (cand[0] == cur[0] and cand[1] < cur[1]):
                        nxt2[key2] = cand
            layer = nxt2
        top = max(v for v, _ in layer.values())
        kbest = min(k for k, (v, _) in layer.items() if v == top)
        tots = layer[kbest][1]
        nodes: dict[str, int] = {}
        for fam, ft in zip(famlist, tots):
            for p, k in zip([q for q in cands if pools[q]["fam"] == fam], table[fam][ft][1]):
                nodes[p] = k
        return nodes, top

    shut: set[str] = set()
    rounds: list[dict[str, Any]] = []
    commit = st["commit"]
    while True:
        nodes, top = optimum(shut)
        if flip == "first_pass":
            break
        tot: dict[str, list] = {}
        for p in cands:
            x = tot.setdefault(pools[p]["cl"], [0, D0])
            x[0] += nodes[p]
            x[1] += pools[p]["curve"][nodes[p]][1]
        short = sorted((v[1], cl) for cl, v in tot.items() if 0 < v[0] < commit.get(cl, 0))
        if not short:
            break
        pick = [cl for _, cl in short] if flip == "close_all" else [short[0][1]]
        for cl in pick:
            rounds.append({"cluster": cl, "min_nodes": commit[cl], "planned_nodes": tot[cl][0], "round": len(rounds) + 1,
                           "saving_exact_cents": _p(tot[cl][1]), "short_clusters": len(short)})
            shut.add(cl)
    famlist = sorted({pools[p]["fam"] for p in cands}, key=lambda f: f.upper())
    st["rounds"] = rounds
    st.update(nodes=nodes, exact_total=top, famlist=famlist)

    show = []
    for p in cands:
        k = nodes[p]
        if not k:
            continue
        sv = _he(pools[p]["curve"][k][1])
        us = puse[p]
        tot = sum(us.values(), D0)
        shares = {a: Decimal(sv) * us[a] / tot for a in us}
        alloc = {a: int(v.to_integral_value(ROUND_FLOOR)) for a, v in shares.items()}
        rest = sv - sum(alloc.values())
        for a in sorted(us, key=lambda a: (alloc[a] - shares[a], a))[:rest]:
            alloc[a] += 1
        for a in sorted(us):
            show.append([p, a, registry[a]["team"], _p(us[a]), str(alloc[a])])
    st["show"] = show
    pub: dict[str, list[int]] = {}
    for r in _rows((root / scal["published_plan"]).read_text(encoding="utf-8"), ","):
        x = pub.setdefault(_k(r["pool_id"]), [int(r["nodes"]), 0])
        x[1] += int(r["saving_cents"])
    st["pub"] = pub
    return st


def _tbl(rows: list[list[Any]], sep: str) -> str:
    return "".join(sep.join(str(c) for c in r) + "\n" for r in rows)


def _js(o: Any) -> str:
    return json.dumps(o, sort_keys=True) + "\n"


def _render(st: dict[str, Any]) -> dict[str, str]:
    pools, cands, nodes = st["pools"], st["cands"], st["nodes"]
    f: dict[str, str] = {}
    sav = {p: _he(pools[p]["curve"][nodes[p]][1]) for p in cands}
    cu = {p: Decimal(nodes[p] * pools[p]["b"]) for p in cands}
    mu = {p: nodes[p] * pools[p]["mu"] for p in cands}
    rows = [["pool_id", "family", "cluster", "nodes", "cache_units", "mem_units", "hourly_node_cents", "saving_cents", "served_pct", "utilization_pct"]]
    for p in cands:
        P = pools[p]
        cov = P["curve"][nodes[p]][0]
        rows.append([p, P["fam"], P["cl"], nodes[p], _p(cu[p]), mu[p], _p(cu[p] * P["eff"](cu[p])), sav[p], _pc(cov, sum(P["load"].values(), D0)),
                     _pc(cov, cu[p] * len(P["valid"])) if nodes[p] else ""])
    f["cache_plan.csv"] = _tbl(rows, ",")
    rows = [["pool_id", "nodes", "cache_units", "served_unit_hours", "saving_exact_cents"]]
    rows += [[p, k, _p(Decimal(k * pools[p]["b"])), _p(cv), _p(s)] for p in cands for k, (cv, s) in sorted(pools[p]["curve"].items())]
    f["pool_curves.psv"] = _tbl(rows, "|")
    w0 = st["w0"]
    rows = [["pool_id", "hour_index", "hour_start_utc", "usage_units", "load_units"]]
    rows += [[p, h, _iso(w0 + H1 * h), _p(st["use"][p].get(h, D0)), _p(pools[p]["load"][h])] for p in sorted(pools) for h in pools[p]["valid"]]
    f["pool_hourly.tsv"] = _tbl(rows, "\t")
    rows = [["hour_index", "hour_start_utc", "pools_valid", "load_units", "cache_units", "served_units", "overflow_units"]]
    for h in range(st["nh"]):
        act = [p for p in cands if h in pools[p]["load"]]
        ld = [pools[p]["load"][h] for p in act]
        cc = [cu[p] for p in act]
        rows.append([h, _iso(w0 + H1 * h), len(act), _p(sum(ld, D0)), _p(sum(cc, D0)), _p(sum((min(a, b) for a, b in zip(ld, cc)), D0)),
                     _p(sum((max(D0, a - b) for a, b in zip(ld, cc)), D0))])
    f["hourly_rollup.tsv"] = _tbl(rows, "\t")
    rows = [["pool_id", "family", "cluster", "scan_rate_cents", "node_rate_cents", "node_units", "min_nodes", "growth_pct", "tier_units",
             "tier_discount_pct", "mem_units_per_node", "netted_units", "valid_hours"]]
    rows += [[p, P["fam"], P["cl"], P["rates"][0], P["rates"][1], P["b"], P["m"], P["g"], P["tier"], P["tp"], P["mu"], _p(P["e"]), len(P["valid"])]
             for p, P in sorted(pools.items())]
    f["rates_used.csv"] = _tbl(rows, ",")
    f["ruleset_used.json"] = _js({"adoption_id": st["adoption"], "effective_date": st["eff_date"].isoformat(), "mem_budget_units": st["mem"], "node_cap_total": st["cap"], "saving_rounding": st["rounding"], "sheet": st["sheet"],
                                  "families": [dict(v, family=k) for k, v in sorted(st["fams"].items(), key=lambda kv: kv[0].upper())]})
    f["dedup_report.json"] = _js(st["dedup"])
    f["source_lineage.json"] = _js(st["lineage"])
    f["applied_adjustments.jsonl"] = "".join(_js(x) for x in st["applied"])
    f["project_resolution.csv"] = _tbl([["alias", "canonical", "hops"]] + [[a, *st["proj"](a, st["w1"])] for a in sorted(st["merges"])], ",")
    rows = [["project_id", "team", "project_status", "scope"]]
    for a, r in sorted(st["registry"].items()):
        if r["org"] == st["org"]:
            rows.append([a, r["team"], r["status"], {"": "IN_SCOPE", "CLOSED_PROJECT": "CLOSED", "DEV_PROJECT": "DEV"}[st["scope"](a)]])
    f["scope_projects.csv"] = _tbl(rows, ",")
    f["excluded_queries.jsonl"] = "".join(_js(x) for x in st["excl"])
    f["reservation_dispositions.csv"] = _tbl([["reservation_id", "pool_id", "owner_project", "units", "effective_end_utc", "status"]] + st["inv"], ",")
    f["excluded_pools.jsonl"] = "".join(_js(x) for x in st["xpools"])
    f["cluster_commitments.jsonl"] = "".join(_js(x) for x in st["rounds"])
    fr: dict[str, dict[str, int]] = {}
    for p in cands:
        fam = pools[p]["fam"]
        d = fr.setdefault(fam.upper(), {"family_cap": st["fams"][fam]["family_cap"], "mem_units": 0, "nodes": 0, "pools": 0, "saving_cents": 0})
        d["nodes"] += nodes[p]
        d["mem_units"] += mu[p]
        d["pools"] += 1
        d["saving_cents"] += sav[p]
    f["family_rollup.json"] = _js(fr)
    xml = [f'<clusters plan="{st["scal"]["plan_id"]}">']
    for cl in sorted({pools[p]["cl"] for p in cands}):
        ps = [p for p in cands if pools[p]["cl"] == cl]
        xml.append(f'<cluster code="{cl}" pools="{len(ps)}" nodes="{sum(nodes[p] for p in ps)}" cache_units="{_p(sum((cu[p] for p in ps), D0))}" '
                   f'mem_units="{sum(mu[p] for p in ps)}" saving_cents="{sum(sav[p] for p in ps)}"/>')
    xml.append("</clusters>")
    f["cluster_rollup.xml"] = "\n".join(xml) + "\n"
    f["chargeback.csv"] = _tbl([["pool_id", "project_id", "team", "usage_units", "allocated_cents"]] + st["show"], ",")
    tm: dict[str, list] = {}
    for _, a, t, _, c in st["show"]:
        x = tm.setdefault(t, [set(), 0])
        x[0].add(a)
        x[1] += int(c)
    f["team_rollup.json"] = _js({t: {"allocated_cents": x[1], "projects": len(x[0])} for t, x in tm.items()})
    f["plan_summary.json"] = _js({"candidate_pools": len(cands), "closure_rounds": len(st["rounds"]), "chargeback_total_cents": sum(int(r[4]) for r in st["show"]),
                                  "excluded_queries": len(st["excl"]), "lookback_hours": st["nh"], "mem_budget_units": st["mem"],
                                  "mem_units_total": sum(mu.values()), "netted_units_total": _p(sum(st["netted"].values(), D0)),
                                  "node_cap_total": st["cap"], "nodes_total": sum(nodes.values()), "out_of_window_queries": st["oow"],
                                  "plan_id": st["scal"]["plan_id"], "ruleset_version": st["sheet"],
                                  "selected_pools": sum(1 for p in cands if nodes[p]), "total_saving_cents": _he(st["exact_total"])})
    pub = st["pub"]
    rows = [["pool_id", "published_nodes", "corrected_nodes", "node_delta", "published_saving_cents", "corrected_saving_cents", "status"]]
    for p in sorted(set(pub) | set(cands)):
        pb, ps = pub.get(p, [None, None])
        cb = nodes.get(p) if p in nodes else None
        cs = sav.get(p)
        status = "NEW" if pb is None else "DROPPED" if cb is None else "MATCH" if cb == pb else "CHANGED"
        rows.append([p, "" if pb is None else pb, "" if cb is None else cb, (cb or 0) - (pb or 0), "" if ps is None else ps, "" if cs is None else cs, status])
    f["variance_vs_published.csv"] = _tbl(rows, ",")
    pf: dict[str, int] = {}
    for p, (b, _) in pub.items():
        pf[p.split("@")[0]] = pf.get(p.split("@")[0], 0) + b
    cf: dict[str, int] = {}
    for p in cands:
        cf[p.split("@")[0]] = cf.get(p.split("@")[0], 0) + nodes[p]
    md = [f"# Plan {st['scal']['plan_id']} cache reconciliation", "", "| family | published_nodes | corrected_nodes | delta_nodes |", "|---|---|---|---|"]
    md += [f"| {x} | {pf.get(x, 0)} | {cf.get(x, 0)} | {cf.get(x, 0) - pf.get(x, 0)} |" for x in sorted(set(pf) | set(cf))]
    md.append(f"| ALL | {sum(pf.values())} | {sum(cf.values())} | {sum(cf.values()) - sum(pf.values())} |")
    f["reconciliation.md"] = "\n".join(md) + "\n"
    return f


def _st(root: Path) -> dict[str, Any]:
    with _LOCK:
        k = "state:" + str(root)
        if k not in _MEMO:
            _MEMO[k] = _state(root)
        return _MEMO[k]


def derive(root: Path) -> dict[str, str]:
    with _LOCK:
        k = "derive:" + str(root)
        if k not in _MEMO:
            _MEMO[k] = _render(_st(root))
        return _MEMO[k]


# =========================================================================== comparison
def _canon(name: str, text: str) -> Any:
    if name.endswith(".json"):
        return json.dumps(json.loads(text), sort_keys=True)
    if name.endswith(".jsonl"):
        return [json.dumps(json.loads(ln), sort_keys=True) for ln in text.splitlines() if ln.strip()]
    if name.endswith(".xml"):
        root = ET.fromstring(text)
        return (root.tag, dict(root.attrib), [(c.tag, dict(c.attrib)) for c in root])
    if name.endswith(".md"):
        out = []
        for ln in text.splitlines():
            ln = ln.strip()
            if ln.startswith("|"):
                out.append(tuple(c.strip() for c in ln.strip("|").split("|")))
            elif ln:
                out.append(" ".join(ln.split()))
        return out
    sep = {".csv": ",", ".tsv": "\t", ".psv": "|"}[Path(name).suffix]
    return [r for r in csv.reader(io.StringIO(text.lstrip("\ufeff")), delimiter=sep) if r]


def _same(name: str, got: str, want: str) -> bool:
    try:
        return _canon(name, got) == _canon(name, want)
    except Exception:
        return False


