@criterion(description="The program, all twenty-two contract reports and manifest.json exist under /app/out")
def deliverables_present(workspace: Path) -> bool:
    return PROGRAM.is_file() and all((OUT / n).is_file() for n in NAMES + ["manifest.json"])


@criterion(description="The program runs on a fresh copy of the corpus at another path and writes all twenty-three files")
def program_writes_contract_files(workspace: Path) -> bool:
    def chk() -> bool:
        out = _run(_clone(_fresh("copy")), "copy")
        return out is not None and all((out / n).is_file() for n in NAMES + ["manifest.json"])
    return _safe(chk)


@criterion(description="Every delimited report in /app/out starts with the exact header line of the output contract")
def delimited_headers_exact(workspace: Path) -> bool:
    def chk() -> bool:
        want = derive(_shipped())
        for n in NAMES:
            if n.endswith((".csv", ".tsv", ".psv")):
                got = _mine(n)
                if got is None or got.split("\n", 1)[0] != want[n].split("\n", 1)[0]:
                    return False
        return True
    return _safe(chk)


@criterion(description="The JSON reports in /app/out parse and carry the top-level keys the output contract names")
def json_report_keys(workspace: Path) -> bool:
    def chk() -> bool:
        want = derive(_shipped())
        for n in ("plan_summary.json", "ruleset_used.json", "dedup_report.json"):
            got = json.loads(_mine(n) or "")
            if not isinstance(got, dict) or set(got) != set(json.loads(want[n])):
                return False
        return True
    try:
        return _safe(chk)
    except (OSError, ValueError, TypeError, KeyError):
        return False


@criterion(description="manifest.json lists every other report in contract order with its true size and SHA-256 digest")
def manifest_consistent(workspace: Path) -> bool:
    def chk() -> bool:
        man = json.loads((OUT / "manifest.json").read_text(encoding="utf-8"))
        if [x["name"] for x in man["files"]] != NAMES:
            return False
        for x in man["files"]:
            blob = (OUT / x["name"]).read_bytes()
            if x["bytes"] != len(blob) or x["sha256"] != hashlib.sha256(blob).hexdigest():
                return False
        return True
    try:
        return _safe(chk)
    except (OSError, ValueError, TypeError, KeyError):
        return False


@criterion(description="Every report in /app/out is UTF-8 text with LF line endings and a final newline unless it is an empty JSON Lines file")
def text_serialization(workspace: Path) -> bool:
    def chk() -> bool:
        for n in NAMES + ["manifest.json"]:
            text = (OUT / n).read_bytes().decode("utf-8")
            if "\r" in text or (text and not text.endswith("\n")) or (not text and not n.endswith(".jsonl")):
                return False
        return True
    try:
        return _safe(chk)
    except (OSError, ValueError, TypeError, KeyError):
        return False


