# =========================================================================== negative checks (True when the cheat or wrong reading is present)
def _echoes_shipped() -> bool:
    root = _held_out("h_track")
    want_v = derive(root)["cache_plan.csv"]
    want_s = derive(_shipped())["cache_plan.csv"]
    if _same("cache_plan.csv", want_v, want_s):
        return False
    got = _out_text(_run(root, "h_track"), "cache_plan.csv")
    return got is not None and _same("cache_plan.csv", got, want_s)


@criterion(description="The program ignores its input and replays the shipped cache plan on a held-out corpus")
def negative_hardcoded_sample_answers(workspace: Path) -> bool:
    # inverted: True only when the held-out rerun reproduces the shipped plan although its truth differs
    return _safe(_echoes_shipped)


@criterion(description="The program is exact on a copy of the shipped corpus and wrong once only the shard file names change")
def negative_filename_dependent_behaviour(workspace: Path) -> bool:
    # inverted: True only when renaming shards (and their manifest entries) alone breaks an otherwise exact program
    def chk() -> bool:
        if _echoes_shipped():
            return False
        if not _all_exact(_run(_clone(_fresh("copy")), "copy"), _shipped()):
            return False
        return not _all_exact(_run(_renamed(), "renamed"), _renamed())
    return _safe(chk)


@criterion(description="Two runs of the program on the same corpus copy write different report bytes")
def negative_nondeterministic_output(workspace: Path) -> bool:
    # inverted: True only when two complete runs disagree on at least one report
    def chk() -> bool:
        a = _run(_clone(_fresh("copy")), "copy")
        b = _run(_clone(_fresh("copy2")), "copy2")
        if a is None or b is None:
            return False
        return any(_out_text(a, n) != _out_text(b, n) for n in NAMES)
    return _safe(chk)


@criterion(description="The delivered source refers to verifier paths or grading files")
def negative_touches_grader(workspace: Path) -> bool:
    # inverted: True when the program names the grader's files or directory
    src = _sources().lower()
    return any(t in src for t in ("/tests/", "test_output", "judge.toml", "rewardkit"))


@criterion(description="The delivered source imports a third-party or network package")
def negative_third_party_or_network(workspace: Path) -> bool:
    # inverted: True when a banned import is present
    def chk() -> bool:
        banned = {"requests", "urllib3", "httpx", "socket", "pandas", "numpy", "openpyxl", "pypdf", "PyPDF2", "yaml",
                  "xlrd", "fitz", "pdfplumber", "lxml", "pdfminer", "scipy", "pulp", "ortools"}
        for p in OUT.glob("*.py"):
            for node in ast.walk(ast.parse(p.read_text(encoding="utf-8"))):
                if isinstance(node, ast.Import):
                    names = {a.name.split(".")[0] for a in node.names}
                elif isinstance(node, ast.ImportFrom):
                    names = {(node.module or "").split(".")[0]}
                else:
                    continue
                if names & banned:
                    return True
        return False
    try:
        return _safe(chk)
    except (OSError, ValueError, TypeError, KeyError):
        return False


@criterion(description="cache_plan.csv repeats the node counts of the faulty published plan for most shared pools")
def negative_echoes_published(workspace: Path) -> bool:
    # inverted: True when the published node counts are copied
    def chk() -> bool:
        got = _plan_nodes(_mine("cache_plan.csv") or "")
        st = _st(_shipped())
        pub = {p: v[0] for p, v in st["pub"].items()}
        common = [p for p in pub if p in got]
        echo = sum(1 for p in common if got[p] == pub[p])
        base = sum(1 for p in common if st["nodes"].get(p) == pub[p])
        return len(common) >= 5 and echo >= 0.6 * len(common) and base < 0.3 * len(common)
    return _safe(chk)


@criterion(description="ruleset_used.json names a workbook sheet whose adoption is not in force at the lookback start")
def negative_unadopted_ruleset_sheet(workspace: Path) -> bool:
    # inverted: True when the draft sheet or a later adoption is reported as the sheet in force
    def chk() -> bool:
        got = json.loads(_mine("ruleset_used.json") or "{}")
        return isinstance(got, dict) and got.get("sheet") in ("DRAFT_RS-C4C", "RS-C4D") and _st(_shipped())["sheet"] != got.get("sheet")
    try:
        return _safe(chk)
    except (OSError, ValueError, TypeError, KeyError):
        return False


@criterion(description="rates_used.csv carries a RESCINDED Table E-1 value where a different rate is in force")
def negative_rescinded_erratum(workspace: Path) -> bool:
    # inverted: True when a rescinded value shows up as the rate in force
    def chk() -> bool:
        st = _st(_shipped())
        rows = _canon("rates_used.csv", _mine("rates_used.csv") or "")
        if not rows:
            return False
        head = rows[0]
        ix = {n: head.index(n) for n in ("pool_id", "scan_rate_cents", "node_rate_cents")}
        got = {r[ix["pool_id"]]: (r[ix["scan_rate_cents"]], r[ix["node_rate_cents"]]) for r in rows[1:]}
        for fam, cl, fld, val, status in st["errata"]:
            pid = fam.upper() + "@" + cl
            if status != "RESCINDED" or pid not in got or pid not in st["pools"]:
                continue
            j = 0 if fld == "scan_rate_cents" else 1
            if got[pid][j] == val and st["pools"][pid]["rates"][j] != val:
                return True
        return False
    return _safe(chk)


@criterion(description="The delivered cache plan uses more memory units than mem_budget_units of the sheet in force allows")
def negative_memory_budget_exceeded(workspace: Path) -> bool:
    # inverted: True when the delivered node counts break the memory budget
    def chk() -> bool:
        st = _st(_shipped())
        got = _plan_nodes(_mine("cache_plan.csv") or "")
        used = 0
        for p, k in got.items():
            fam = p.split("@")[0].lower()
            if fam not in st["fams"]:
                return False
            used += k * st["fams"][fam]["mem_units_per_node"]
        return bool(got) and used > st["mem"]
    return _safe(chk)


