@criterion(description="total_saving_cents is the sum of the rounded pool savings on a corpus where that differs from the once-rounded exact total")
def negative_rounded_total(workspace: Path) -> bool:
    # inverted: True when the summed rounded figure is reported instead of the once-rounded exact total
    def fired(root: Path, out: Path | None) -> bool:
        st = _st(root)
        once = _he(st["exact_total"])
        summed = sum(_he(st["pools"][p]["curve"][st["nodes"][p]][1]) for p in st["cands"])
        if once == summed or out is None:
            return False
        for n in ("cache_plan.csv", "pool_curves.psv"):
            mine = _out_text(out, n)
            if mine is None or not _same(n, mine, derive(root)[n]):
                return False
        got = json.loads(_out_text(out, "plan_summary.json") or "{}")
        return isinstance(got, dict) and got.get("total_saving_cents") == summed

    def chk() -> bool:
        cases = [(_shipped(), OUT)] + [(_held_out(t), _run(_held_out(t), t)) for t in HELD_OUT]
        return any(_safe(lambda r=r, o=o: fired(r, o)) for r, o in cases)
    try:
        return _safe(chk)
    except (OSError, ValueError, TypeError, KeyError):
        return False


